do $v2$ declare v_count integer; v_marks integer; v_expected jsonb:='{"phy-p2-1-q1::a":{"answer":"1/V for 12.0 cm³ = 8.33 × 10⁻²; for 20.0 cm³ = 5.00 × 10⁻²; for 30.0 cm³ = 3.33 × 10⁻²","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"XS","description":"divides 1 by the volume for at least one row","field":"all","manual":true},{"code":"A1","kind":"A","marks":2,"profile":"UK","description":"8.33 × 10⁻² cm⁻³","field":"all","manual":true},{"code":"A2","kind":"A","marks":2,"profile":"UK","description":"5.00 × 10⁻² cm⁻³","field":"all","manual":true},{"code":"A3","kind":"A","marks":1,"profile":"UK","description":"3.33 × 10⁻² cm⁻³","field":"all","manual":true}],"solution":"1/V for 12.0 cm³ = 8.33 × 10⁻²; for 20.0 cm³ = 5.00 × 10⁻²; for 30.0 cm³ = 3.33 × 10⁻²\n\nMarker''s note. Accept 8.3, 5.0 and 3.3. Do not penalise a candidate who works in cm⁻³ without the × 10⁻² so long as the values are consistent with the column heading.","markerNote":"Accept 8.3, 5.0 and 3.3. Do not penalise a candidate who works in cm⁻³ without the × 10⁻² so long as the values are consistent with the column heading.","responseType":"table","answerType":"text"},"phy-p2-1-q1::b":{"answer":"A straight line through the origin","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"XS","description":"both axes labelled with the quantity and its unit","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"the scales asked for are used, and the points fill at least half the grid","field":"all","manual":true},{"code":"B3","kind":"B","marks":3,"profile":"XS","description":"all six points plotted correctly; deduct one mark for each point misplaced","field":"all","manual":true},{"code":"B4","kind":"B","marks":2,"profile":"XS","description":"a single best fit straight line drawn through the points and the origin","field":"all","manual":true}],"solution":"A straight line through the origin\n\nMarker''s note. A dot to dot line scores nothing for B4. A line drawn with a ruler which misses the origin still scores B4 if the points justify it.","markerNote":"A dot to dot line scores nothing for B4. A line drawn with a ruler which misses the origin still scores B4 if the points justify it.","responseType":"graph","answerType":"text"},"phy-p2-1-q1::c":{"answer":"gradient = 2400 kPa cm³","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":2,"profile":"XS","description":"a triangle drawn on the line, using at least half its length","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"XS","description":"gradient in the range 2300 to 2500","field":"all","manual":true},{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the unit kPa cm³","field":"all","manual":true}],"solution":"gradient = 2400 kPa cm³\n\nMarker''s note. The gradient is P ÷ (1/V), so the unit is kPa ÷ cm⁻³, which is kPa cm³. Accept the unit written as kPa cm³ or as kPa/cm⁻³. A gradient taken from two table values instead of from the line loses M1 but may still earn A1.","markerNote":"The gradient is P ÷ (1/V), so the unit is kPa ÷ cm⁻³, which is kPa cm³. Accept the unit written as kPa cm³ or as kPa/cm⁻³. A gradient taken from two table values instead of from the line loses M1 but may still earn A1.","responseType":null,"answerType":"text"},"phy-p2-1-q1::d":{"answer":"133 kPa","modelResponse":"133 kPa","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"1/V = 1/18.0 = 5.56 × 10⁻² cm⁻³","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"reads the pressure off the line at that value of 1/V","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"133 kPa, accept 128 to 138 kPa","field":"answer","check":{"type":"value","value":133,"tolerance":0.02,"unit":"kPa"}}],"solution":"133 kPa\n\nMarker''s note. A candidate who calculates 2400/18 rather than reading the graph has not done what was asked but has the physics right: award M1 and A1, withhold M2. Follow through from the candidate''s own earlier value.","markerNote":"A candidate who calculates 2400/18 rather than reading the graph has not done what was asked but has the physics right: award M1 and A1, withhold M2. Follow through from the candidate''s own earlier value.","responseType":null,"answerType":"value"},"phy-p2-1-q1::e":{"answer":"inversely proportional; temperature; the constant PV for that mass of gas","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"inversely proportional","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"temperature","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"the product of pressure and volume, PV, for that mass of gas","field":"all","manual":true}],"solution":"inversely proportional; temperature; the constant PV for that mass of gas\n\nMarker''s note. For B3 accept ''the constant in PV = constant'', or ''P × V'', or the numerical value 2400 kPa cm³.","markerNote":"For B3 accept ''the constant in PV = constant'', or ''P × V'', or the numerical value 2400 kPa cm³.","responseType":null,"answerType":"text"},"phy-p2-1-q1::f":{"answer":"Allow time for the temperature of the gas to settle before each reading is taken","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"XS","description":"one specific precaution, with the reason it matters","field":"all","manual":true}],"solution":"Allow time for the temperature of the gas to settle before each reading is taken\n\nMarker''s note. Accept: wait for the temperature to become steady, since the law holds only at constant temperature; read the scale square on to avoid parallax; check the gauge for a zero error; change the volume slowly so that no heating occurs. Award one mark only where the precaution is named without a reason. Refuse ''be careful'' and ''avoid human error''.","markerNote":"Accept: wait for the temperature to become steady, since the law holds only at constant temperature; read the scale square on to avoid parallax; check the gauge for a zero error; change the volume slowly so that no heating occurs. Award one mark only where the precaution is named without a reason. Refuse ''be careful'' and ''avoid human error''.","responseType":null,"answerType":"text"},"phy-p2-1-q2::ai":{"answer":"Density is the mass per unit volume of a substance.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"mass per unit volume","field":"all","manual":true}],"solution":"Density is the mass per unit volume of a substance.\n\nMarker''s note. Accept density = mass ÷ volume.","markerNote":"Accept density = mass ÷ volume.","responseType":null,"answerType":"text"},"phy-p2-1-q2::aii":{"answer":"kg m⁻³","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"kg m⁻³","field":"all","manual":true}],"solution":"kg m⁻³\n\nMarker''s note. Accept kg/m³. Do not accept g cm⁻³, which is not the SI unit.","markerNote":"Accept kg/m³. Do not accept g cm⁻³, which is not the SI unit.","responseType":null,"answerType":"text"},"phy-p2-1-q2::bi":{"answer":"1.0 × 10⁻³ m³","modelResponse":"0.001 m³","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"converts all three lengths to metres and multiplies","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"1.0 × 10⁻³ m³","field":"answer","check":{"type":"value","value":0.001,"tolerance":0.02,"unit":"m³"}}],"solution":"1.0 × 10⁻³ m³\n\nMarker''s note. 0.20 × 0.10 × 0.050. A candidate who works in cm³ and gets 1000 cm³ earns M1 only, unless the conversion to m³ then follows.","markerNote":"0.20 × 0.10 × 0.050. A candidate who works in cm³ and gets 1000 cm³ earns M1 only, unless the conversion to m³ then follows.","responseType":null,"answerType":"value"},"phy-p2-1-q2::bii":{"answer":"2700 kg m⁻³","modelResponse":"2700 kg m⁻³","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"density = mass ÷ volume","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"2700 kg m⁻³","field":"answer","check":{"type":"value","value":2700,"tolerance":0.02,"unit":"kg m⁻³"}}],"solution":"2700 kg m⁻³\n\nMarker''s note. Follow through from the candidate''s own earlier value. A candidate using 1000 cm³ arrives at 2.7 g cm⁻³, which earns M1 and A1 if the unit is given correctly.","markerNote":"Follow through from the candidate''s own earlier value. A candidate using 1000 cm³ arrives at 2.7 g cm⁻³, which earns M1 and A1 if the unit is given correctly.","responseType":null,"answerType":"value"},"phy-p2-1-q2::c":{"answer":"Pressure is the force acting normally per unit area. P = F/A","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"force per unit area, or force acting normally per unit area","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"P = F/A, with the symbols identified","field":"all","manual":true}],"solution":"Pressure is the force acting normally per unit area. P = F/A\n\nMarker''s note. Do not award B1 for ''force over something''. The word area is required.","markerNote":"Do not award B1 for ''force over something''. The word area is required.","responseType":null,"answerType":"text"},"phy-p2-1-q2::d":{"answer":"1350 Pa","modelResponse":"1350 Pa","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"weight = mg = 2.7 × 10 = 27 N","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"largest face has area 0.20 × 0.10 = 0.020 m²","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"1350 Pa, with the unit","field":"answer","check":{"type":"value","value":1350,"tolerance":0.02,"unit":"Pa"}}],"solution":"1350 Pa\n\nMarker''s note. Accept 1.35 × 10³ Pa or 1350 N m⁻². A candidate who uses the mass in place of the weight and gets 135 loses A1 but keeps M2.","markerNote":"Accept 1.35 × 10³ Pa or 1350 N m⁻². A candidate who uses the mass in place of the weight and gets 135 loses A1 but keeps M2.","responseType":null,"answerType":"value"},"phy-p2-1-q2::e":{"answer":"The smallest face, because pressure is inversely proportional to area for a fixed force.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"the smallest face, the 10 cm by 5.0 cm face","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the reason: the same weight acts on a smaller area","field":"all","manual":true}],"solution":"The smallest face, because pressure is inversely proportional to area for a fixed force.\n\nMarker''s note. The reason mark stands alone. A candidate who names the wrong face but gives the correct general reason still earns B2.","markerNote":"The reason mark stands alone. A candidate who names the wrong face but gives the correct general reason still earns B2.","responseType":null,"answerType":"text"},"phy-p2-1-q2::f":{"answer":"1.55 × 10⁵ Pa","modelResponse":"155000 Pa","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses P = hρg","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"154 500 Pa, accept 1.5 × 10⁵ Pa","field":"answer","check":{"type":"value","value":155000,"tolerance":0.02,"unit":"Pa"}}],"solution":"1.55 × 10⁵ Pa\n\nMarker''s note. The question asks for the pressure due to the water alone, so atmospheric pressure is not to be added. A candidate who adds 1.0 × 10⁵ Pa has answered a different question and loses A1 but keeps M1.","markerNote":"The question asks for the pressure due to the water alone, so atmospheric pressure is not to be added. A candidate who adds 1.0 × 10⁵ Pa has answered a different question and loses A1 but keeps M1.","responseType":null,"answerType":"value"},"phy-p2-1-q3::a":{"answer":"Energy can neither be created nor destroyed; it can only be changed from one form to another.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"energy cannot be created or destroyed","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"it is converted from one form to another, or transferred from one body to another","field":"all","manual":true}],"solution":"Energy can neither be created nor destroyed; it can only be changed from one form to another.\n\nMarker''s note. Accept ''the total energy of a closed system is constant'' for both marks.","markerNote":"Accept ''the total energy of a closed system is constant'' for both marks.","responseType":null,"answerType":"text"},"phy-p2-1-q3::bi":{"answer":"6.0 × 10⁴ J","modelResponse":"60000 J","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"work done against gravity = mgh","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 500 × 10 × 12","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"60 000 J, with the unit","field":"answer","check":{"type":"value","value":60000,"tolerance":0.02,"unit":"J"}}],"solution":"6.0 × 10⁴ J\n\nMarker''s note. Accept 6.0 × 10⁴ J or 60 kJ.","markerNote":"Accept 6.0 × 10⁴ J or 60 kJ.","responseType":null,"answerType":"value"},"phy-p2-1-q3::bii":{"answer":"1500 W","modelResponse":"1500 W","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"power = work done ÷ time taken","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"1500 W, with the unit","field":"answer","check":{"type":"value","value":1500,"tolerance":0.02,"unit":"W"}}],"solution":"1500 W\n\nMarker''s note. Follow through from the candidate''s own earlier value. Accept 1.5 kW.","markerNote":"Follow through from the candidate''s own earlier value. Accept 1.5 kW.","responseType":null,"answerType":"value"},"phy-p2-1-q3::c":{"answer":"60 per cent","modelResponse":"60","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"efficiency = useful output ÷ total input","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"multiplies by 100 to give a percentage","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"60 per cent","field":"answer","check":{"type":"value","value":60,"tolerance":0.02}}],"solution":"60 per cent\n\nMarker''s note. Follow through from the candidate''s own earlier value. A candidate who leaves the answer as 0.6 without the percentage earns M1 and A1 but not M2.","markerNote":"Follow through from the candidate''s own earlier value. A candidate who leaves the answer as 0.6 without the percentage earns M1 and A1 but not M2.","responseType":null,"answerType":"value"},"phy-p2-1-q3::d":{"answer":"Some of the input energy is transferred to the surroundings as thermal energy, through friction in the moving parts and resistance in the wires.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"energy is transferred to forms which are not useful","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"names where it goes: friction, heating of the motor, resistance of the wires, sound","field":"all","manual":true}],"solution":"Some of the input energy is transferred to the surroundings as thermal energy, through friction in the moving parts and resistance in the wires.\n\nMarker''s note. ''Energy is lost'' on its own scores nothing, because energy is not lost. The candidate must say what it became.","markerNote":"''Energy is lost'' on its own scores nothing, because energy is not lost. The candidate must say what it became.","responseType":null,"answerType":"text"},"phy-p2-1-q3::e":{"answer":"Solar and wind. The fuel is free and does not have to be imported, which saves foreign exchange.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first renewable source suitable for the Caribbean","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"second, different renewable source","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"one advantage, linked to the island situation","field":"all","manual":true}],"solution":"Solar and wind. The fuel is free and does not have to be imported, which saves foreign exchange.\n\nMarker''s note. Accept solar, wind, hydroelectric, geothermal, biomass and wave. Do not accept natural gas or nuclear, which are not renewable. For B3 accept: no fuel to import, saves foreign exchange, no carbon dioxide produced during generation, the supply cannot be cut off by a shipping problem.","markerNote":"Accept solar, wind, hydroelectric, geothermal, biomass and wave. Do not accept natural gas or nuclear, which are not renewable. For B3 accept: no fuel to import, saves foreign exchange, no carbon dioxide produced during generation, the supply cannot be cut off by a shipping problem.","responseType":null,"answerType":"text"},"phy-p2-1-q4::a":{"answer":"In a transverse wave the particles vibrate at right angles to the direction of travel; in a longitudinal wave they vibrate along it. Examples: light or a water wave; sound.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"transverse: vibration at right angles to the direction of travel","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"longitudinal: vibration along the direction of travel","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"a correct example of a transverse wave","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"KC","description":"a correct example of a longitudinal wave","field":"all","manual":true}],"solution":"In a transverse wave the particles vibrate at right angles to the direction of travel; in a longitudinal wave they vibrate along it. Examples: light or a water wave; sound.\n\nMarker''s note. The distinction must be made on the direction of vibration relative to the direction of travel. ''One goes up and down and the other goes along'' scores nothing, since both travel along. Accept any electromagnetic wave, or a wave on a rope or water, for B3. B4 requires sound, or a compression wave in a spring.","markerNote":"The distinction must be made on the direction of vibration relative to the direction of travel. ''One goes up and down and the other goes along'' scores nothing, since both travel along. Accept any electromagnetic wave, or a wave on a rope or water, for B3. B4 requires sound, or a compression wave in a spring.","responseType":null,"answerType":"text"},"phy-p2-1-q4::b":{"answer":"330 m s⁻¹","modelResponse":"330 m s⁻¹","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses v = f λ","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 500 × 0.66","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"330 m s⁻¹, with the unit","field":"answer","check":{"type":"value","value":330,"tolerance":0.02,"unit":"m s⁻¹"}}],"solution":"330 m s⁻¹","markerNote":null,"responseType":null,"answerType":"value"},"phy-p2-1-q4::c":{"answer":"330 m s⁻¹","modelResponse":"330 m s⁻¹","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"recognises that the sound travels 2 × 165 = 330 m","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"speed = distance ÷ time","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"330 m s⁻¹, with the unit","field":"answer","check":{"type":"value","value":330,"tolerance":0.02,"unit":"m s⁻¹"}}],"solution":"330 m s⁻¹\n\nMarker''s note. Forgetting to double the distance gives 165 m s⁻¹: award M2 only. This is the commonest error in the question.","markerNote":"Forgetting to double the distance gives 165 m s⁻¹: award M2 only. This is the commonest error in the question.","responseType":null,"answerType":"value"},"phy-p2-1-q4::di":{"answer":"Sound of a frequency above the upper limit of human hearing, above about 20 kHz.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"frequency above the range of human hearing","field":"all","manual":true}],"solution":"Sound of a frequency above the upper limit of human hearing, above about 20 kHz.\n\nMarker''s note. Accept ''above 20 000 Hz''.","markerNote":"Accept ''above 20 000 Hz''.","responseType":null,"answerType":"text"},"phy-p2-1-q4::dii":{"answer":"Scanning an unborn baby. Ultrasound is not ionising, so it does not damage living cells.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"a genuine use","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"a reason connected to that use","field":"all","manual":true}],"solution":"Scanning an unborn baby. Ultrasound is not ionising, so it does not damage living cells.\n\nMarker''s note. Accept: pre-natal scanning, imaging soft tissue, breaking up kidney stones, depth sounding at sea, checking castings for cracks. The reason must fit the use: for a medical use, that ultrasound does not ionise and so does not damage cells; for depth sounding, that sound travels well through water while light does not.","markerNote":"Accept: pre-natal scanning, imaging soft tissue, breaking up kidney stones, depth sounding at sea, checking castings for cracks. The reason must fit the use: for a medical use, that ultrasound does not ionise and so does not damage cells; for depth sounding, that sound travels well through water while light does not.","responseType":null,"answerType":"text"},"phy-p2-1-q4::e":{"answer":"Pitch is determined by frequency. Loudness is determined by amplitude.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"frequency","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"amplitude","field":"all","manual":true}],"solution":"Pitch is determined by frequency. Loudness is determined by amplitude.\n\nMarker''s note. Do not accept wavelength for pitch, since the question asks for the wave parameter which determines it and the medium fixes the relationship.","markerNote":"Do not accept wavelength for pitch, since the question asks for the wave parameter which determines it and the medium fixes the relationship.","responseType":null,"answerType":"text"},"phy-p2-1-q5::a":{"answer":"Electric current is the rate of flow of charge. Its SI unit is the ampere.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"rate of flow of charge, or charge passing a point per unit time","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"the ampere, A","field":"all","manual":true}],"solution":"Electric current is the rate of flow of charge. Its SI unit is the ampere.\n\nMarker''s note. Do not accept ''the flow of electricity''.","markerNote":"Do not accept ''the flow of electricity''.","responseType":null,"answerType":"text"},"phy-p2-1-q5::b":{"answer":"The current through a metallic conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions remain constant.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"current is proportional to potential difference","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the condition: constant temperature, or constant physical conditions","field":"all","manual":true}],"solution":"The current through a metallic conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions remain constant.\n\nMarker''s note. A statement of V = IR without the word proportional is not a statement of the law and scores B1 only if proportionality is implied clearly. The condition is required for B2 and is the mark most often dropped.","markerNote":"A statement of V = IR without the word proportional is not a statement of the law and scores B1 only if proportionality is implied clearly. The condition is required for B2 and is the mark most often dropped.","responseType":null,"answerType":"text"},"phy-p2-1-q5::c":{"answer":"4.0 Ω","modelResponse":"4 Ω","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses 1/R = 1/R₁ + 1/R₂ for the parallel pair","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 1/8.0 + 1/8.0","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"4.0 Ω, with the unit","field":"answer","check":{"type":"value","value":4,"tolerance":0.02,"unit":"Ω"}}],"solution":"4.0 Ω\n\nMarker''s note. Accept the shortcut for two equal resistors, R/2, for M1 and M2 together, provided the working shows it.","markerNote":"Accept the shortcut for two equal resistors, R/2, for M1 and M2 together, provided the working shows it.","responseType":null,"answerType":"value"},"phy-p2-1-q5::d":{"answer":"6.0 Ω","modelResponse":"6 Ω","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"adds the series resistance to the parallel combination","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"6.0 Ω, with the unit","field":"answer","check":{"type":"value","value":6,"tolerance":0.02,"unit":"Ω"}}],"solution":"6.0 Ω\n\nMarker''s note. Follow through from the candidate''s own earlier value.","markerNote":"Follow through from the candidate''s own earlier value.","responseType":null,"answerType":"value"},"phy-p2-1-q5::e":{"answer":"2.0 A","modelResponse":"2 A","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses I = V/R with the total resistance","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"2.0 A, with the unit","field":"answer","check":{"type":"value","value":2,"tolerance":0.02,"unit":"A"}}],"solution":"2.0 A\n\nMarker''s note. Follow through from the candidate''s own earlier value.","markerNote":"Follow through from the candidate''s own earlier value.","responseType":null,"answerType":"value"},"phy-p2-1-q5::f":{"answer":"4.0 V","modelResponse":"4 V","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses V = IR with the current through the 2.0 Ω resistor","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"4.0 V, with the unit","field":"answer","check":{"type":"value","value":4,"tolerance":0.02,"unit":"V"}}],"solution":"4.0 V\n\nMarker''s note. Follow through from the candidate''s own earlier value. The full current passes through the series resistor, which is the point of the part.","markerNote":"Follow through from the candidate''s own earlier value. The full current passes through the series resistor, which is the point of the part.","responseType":null,"answerType":"value"},"phy-p2-1-q5::g":{"answer":"$5.10","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"energy used = 2 kW × 3 h = 6 kWh","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"6 × 85 cents = 510 cents, that is $5.10","field":"all","manual":true}],"solution":"$5.10\n\nMarker''s note. Accept 510 cents. A candidate who converts to joules and then back correctly earns both marks.","markerNote":"Accept 510 cents. A candidate who converts to joules and then back correctly earns both marks.","responseType":null,"answerType":"text"},"phy-p2-1-q6::a":{"answer":"The half-life is the time taken for half the nuclei of a radioactive sample to decay, or for the activity to fall to half its original value.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the time taken","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"for half the undecayed nuclei to decay, or for the activity to halve","field":"all","manual":true}],"solution":"The half-life is the time taken for half the nuclei of a radioactive sample to decay, or for the activity to fall to half its original value.\n\nMarker''s note. Accept either the nuclei form or the activity form. ''The time for the source to decay'' scores nothing.","markerNote":"Accept either the nuclei form or the activity form. ''The time for the source to decay'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-1-q6::b":{"answer":"Alpha: helium nucleus, +2, stopped by paper. Beta: fast-moving electron, −1, stopped by a few millimetres of aluminium. Gamma: electromagnetic radiation, 0, reduced by several centimetres of lead.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"alpha is a helium nucleus, or 2 protons and 2 neutrons","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"alpha is stopped by paper, or by a few centimetres of air","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"beta has a relative charge of −1","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"KC","description":"beta is stopped by a few millimetres of aluminium","field":"all","manual":true},{"code":"B5","kind":"B","marks":1,"profile":"KC","description":"gamma is electromagnetic radiation, or a high energy photon","field":"all","manual":true},{"code":"B6","kind":"B","marks":1,"profile":"KC","description":"the remaining cell completed correctly","field":"all","manual":true}],"solution":"Alpha: helium nucleus, +2, stopped by paper. Beta: fast-moving electron, −1, stopped by a few millimetres of aluminium. Gamma: electromagnetic radiation, 0, reduced by several centimetres of lead.\n\nMarker''s note. For gamma, accept ''reduced by lead'' rather than ''stopped by lead''; gamma is never completely stopped, so do not require the word stopped. A candidate who writes ''electron'' for beta without ''fast moving'' or ''from the nucleus'' still earns the charge and penetration marks.","markerNote":"For gamma, accept ''reduced by lead'' rather than ''stopped by lead''; gamma is never completely stopped, so do not require the word stopped. A candidate who writes ''electron'' for beta without ''fast moving'' or ''from the nucleus'' still earns the charge and penetration marks.","responseType":"table","answerType":"text"},"phy-p2-1-q6::c":{"answer":"15 minutes","modelResponse":"15 min","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"halves the count rate repeatedly: 800, 400, 200, 100, 50","field":"all","manual":true},{"code":"M2","kind":"M","marks":2,"profile":"UK","description":"identifies that four half-lives have passed","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"60 ÷ 4 = 15 minutes","field":"answer","check":{"type":"value","value":15,"tolerance":0.02,"unit":"min"}}],"solution":"15 minutes\n\nMarker''s note. A candidate who divides 60 by 2 and answers 30 minutes has counted one halving rather than four: award M1 only. Working shown as a table or a sketch graph is acceptable for M1 and M2.","markerNote":"A candidate who divides 60 by 2 and answers 30 minutes has counted one halving rather than four: award M1 only. Working shown as a table or a sketch graph is acceptable for M1 and M2.","responseType":null,"answerType":"value"},"phy-p2-1-q6::d":{"answer":"Use: tracing a leak in an underground pipe. Precautions: handle the source with tongs, and store it in a lead-lined container.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"one beneficial use","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"first precaution","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"XS","description":"second, different precaution","field":"all","manual":true}],"solution":"Use: tracing a leak in an underground pipe. Precautions: handle the source with tongs, and store it in a lead-lined container.\n\nMarker''s note. Uses: medical tracers, treating cancer, sterilising equipment, dating rocks or archaeological remains, thickness gauging, detecting leaks, smoke alarms. Precautions: handle with tongs or forceps, never with bare hands; keep the source pointed away from the body; store in a lead-lined container; limit the time of exposure; wear a film badge. ''Be careful'' scores nothing.","markerNote":"Uses: medical tracers, treating cancer, sterilising equipment, dating rocks or archaeological remains, thickness gauging, detecting leaks, smoke alarms. Precautions: handle with tongs or forceps, never with bare hands; keep the source pointed away from the body; store in a lead-lined container; limit the time of exposure; wear a film badge. ''Be careful'' scores nothing.","responseType":null,"answerType":"text"}}'::jsonb;
begin
 select jsonb_array_length(criteria),
 (select sum((c->>'maxMarks')::integer) from jsonb_array_elements(criteria) c)
 into v_count,v_marks from spark_grading_private.rubrics_v2
 where subject_id='physics' and paper_id='spark-phy-p02-practice-1' and active=false and verification_status='draft';
 if v_count is distinct from 37 or v_marks is distinct from 100
 or (select count(*) from spark_grading_private.rubrics_v2 r
 cross join lateral jsonb_array_elements(r.criteria) c
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-1'
 and v_expected ? (c->>'id')) <> 37
 then raise exception 'Physics/IT exact draft source mismatch for spark-phy-p02-practice-1'; end if;
 update spark_grading_private.rubrics_v2 r set criteria=(
 select jsonb_agg(c || jsonb_build_object('sourceMarking',v_expected->(c->>'id')) order by ordinal)
 from jsonb_array_elements(r.criteria) with ordinality item(c,ordinal))
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-1' and r.active=false and r.verification_status='draft';
end $v2$;
do $v2$ declare v_count integer; v_marks integer; v_expected jsonb:='{"phy-p2-2-q1::a":{"answer":"For l = 0.40 m: T = 1.270 s, T² = 1.613 s². For l = 0.80 m: T = 1.795 s, T² = 3.222 s².","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"divides the time by 20 to obtain the period","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"T = 1.270 s","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"T² = 1.613 s²","field":"all","manual":true},{"code":"A3","kind":"A","marks":1,"profile":"UK","description":"T = 1.795 s","field":"all","manual":true},{"code":"A4","kind":"A","marks":1,"profile":"UK","description":"T² = 3.222 s²","field":"all","manual":true},{"code":"B1","kind":"B","marks":1,"profile":"XS","description":"all values in a column quoted to the same number of decimal places","field":"all","manual":true}],"solution":"For l = 0.40 m: T = 1.270 s, T² = 1.613 s². For l = 0.80 m: T = 1.795 s, T² = 3.222 s².\n\nMarker''s note. Accept 1.27, 1.61, 1.80 and 3.22. Follow through from the candidate''s own earlier value. A candidate who multiplies by 20 instead of dividing loses M1 and every A mark that follows from it.","markerNote":"Accept 1.27, 1.61, 1.80 and 3.22. Follow through from the candidate''s own earlier value. A candidate who multiplies by 20 instead of dividing loses M1 and every A mark that follows from it.","responseType":"table","answerType":"text"},"phy-p2-2-q1::b":{"answer":"A straight line through the origin","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"XS","description":"both axes labelled with the quantity and its unit","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"the scales asked for are used, and the points fill at least half the grid","field":"all","manual":true},{"code":"B3","kind":"B","marks":3,"profile":"XS","description":"all five points plotted correctly; deduct one mark for each point misplaced","field":"all","manual":true},{"code":"B4","kind":"B","marks":2,"profile":"XS","description":"a single best fit straight line drawn","field":"all","manual":true}],"solution":"A straight line through the origin\n\nMarker''s note. Plotting T against l instead of T² against l gives a curve. Award B1 and B2 only, and follow through into Part (c) is then not available.","markerNote":"Plotting T against l instead of T² against l gives a curve. Award B1 and B2 only, and follow through into Part (c) is then not available.","responseType":"graph","answerType":"text"},"phy-p2-2-q1::c":{"answer":"gradient = 4.0 s² m⁻¹","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":2,"profile":"XS","description":"a triangle drawn on the line, using at least half its length","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"XS","description":"gradient in the range 3.8 to 4.2","field":"all","manual":true},{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the unit s² m⁻¹","field":"all","manual":true}],"solution":"gradient = 4.0 s² m⁻¹\n\nMarker''s note. Accept s²/m. A gradient calculated from two of the table values rather than from the drawn line loses M1.","markerNote":"Accept s²/m. A gradient calculated from two of the table values rather than from the drawn line loses M1.","responseType":null,"answerType":"text"},"phy-p2-2-q1::d":{"answer":"g = 9.8 m s⁻²","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"squares the equation to give T² = (4π²/g) l","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"XS","description":"identifies the gradient as 4π²/g","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"XS","description":"rearranges to g = 4π² ÷ gradient","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"9.8 m s⁻², accept 9.4 to 10.4, with the unit","field":"all","manual":true}],"solution":"g = 9.8 m s⁻²\n\nMarker''s note. Follow through from the candidate''s own earlier value. A candidate who writes g = 4π² × gradient obtains about 158 and loses A1 and A2, but keeps M1 and M2. An answer with no unit loses A2.","markerNote":"Follow through from the candidate''s own earlier value. A candidate who writes g = 4π² × gradient obtains about 158 and loses A1 and A2, but keeps M1 and M2. An answer with no unit loses A2.","responseType":null,"answerType":"text"},"phy-p2-2-q1::e":{"answer":"Timing 20 oscillations and dividing by 20 spreads the reaction time error over 20 swings, so the error in a single period is much smaller.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"identifies the error: human reaction time in starting and stopping the watch","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"explains that dividing by 20 reduces the effect of that error on the period","field":"all","manual":true}],"solution":"Timing 20 oscillations and dividing by 20 spreads the reaction time error over 20 swings, so the error in a single period is much smaller.\n\nMarker''s note. ''To be more accurate'' on its own scores nothing. The candidate must name the error or explain the averaging.","markerNote":"''To be more accurate'' on its own scores nothing. The candidate must name the error or explain the averaging.","responseType":null,"answerType":"text"},"phy-p2-2-q1::f":{"answer":"Keep the angle of swing small, no more than about 10 degrees.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"XS","description":"one specific precaution, with the reason it matters","field":"all","manual":true}],"solution":"Keep the angle of swing small, no more than about 10 degrees.\n\nMarker''s note. Accept: keep the angle small, because the relationship does not hold for large angles; measure the length to the centre of the bob; make sure the bob swings in one vertical plane rather than in a circle; clamp the string firmly so the length does not change; start counting at zero rather than at one. One mark where the precaution is named without a reason.","markerNote":"Accept: keep the angle small, because the relationship does not hold for large angles; measure the length to the centre of the bob; make sure the bob swings in one vertical plane rather than in a circle; clamp the string firmly so the length does not change; start counting at zero rather than at one. One mark where the precaution is named without a reason.","responseType":null,"answerType":"text"},"phy-p2-2-q2::a":{"answer":"When a body is in equilibrium, the sum of the clockwise moments about any point equals the sum of the anticlockwise moments about that same point.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"sum of clockwise moments","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"equals the sum of anticlockwise moments","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"about the same point, and the body is in equilibrium","field":"all","manual":true}],"solution":"When a body is in equilibrium, the sum of the clockwise moments about any point equals the sum of the anticlockwise moments about that same point.\n\nMarker''s note. B3 requires either ''about the same point'' or ''when the body is in equilibrium''. Both together are not needed.","markerNote":"B3 requires either ''about the same point'' or ''when the body is in equilibrium''. Both together are not needed.","responseType":null,"answerType":"text"},"phy-p2-2-q2::b":{"answer":"The resultant force on the body must be zero.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the forces on the body must balance, or the resultant force is zero","field":"all","manual":true}],"solution":"The resultant force on the body must be zero.\n\nMarker''s note. Accept ''sum of upward forces equals sum of downward forces''.","markerNote":"Accept ''sum of upward forces equals sum of downward forces''.","responseType":null,"answerType":"text"},"phy-p2-2-q2::c":{"answer":"The moment of a force about a point is the force multiplied by the perpendicular distance from the point to the line of action of the force. Its unit is the newton metre.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"force multiplied by distance","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"the distance is the perpendicular distance from the point to the line of action","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"N m","field":"all","manual":true}],"solution":"The moment of a force about a point is the force multiplied by the perpendicular distance from the point to the line of action of the force. Its unit is the newton metre.\n\nMarker''s note. The word perpendicular is required for B2. Do not accept the joule for B3, even though a joule is also a newton times a metre: in a moment the distance is measured at right angles to the force, not along it.","markerNote":"The word perpendicular is required for B2. Do not accept the joule for B3, even though a joule is also a newton times a metre: in a moment the distance is measured at right angles to the force, not along it.","responseType":null,"answerType":"text"},"phy-p2-2-q2::d":{"answer":"0.60 N m","modelResponse":"0.6 N m","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"distance from the pivot = 50 − 20 = 30 cm","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"converts to 0.30 m and multiplies by 2.0 N","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"0.60 N m, with the unit","field":"answer","check":{"type":"value","value":0.6,"tolerance":0.02,"unit":"N m"}}],"solution":"0.60 N m\n\nMarker''s note. Accept 60 N cm with the unit given. A candidate who uses 20 cm rather than 30 cm has measured from the end of the rule rather than the pivot: award M2 only if the method is otherwise correct.","markerNote":"Accept 60 N cm with the unit given. A candidate who uses 20 cm rather than 30 cm has measured from the end of the rule rather than the pivot: award M2 only if the method is otherwise correct.","responseType":null,"answerType":"value"},"phy-p2-2-q2::e":{"answer":"The 70 cm mark","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"applies the principle of moments: 2.0 × 0.30 = 3.0 × d","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"d = 0.60 ÷ 3.0 = 0.20 m","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"0.20 m, that is 20 cm, from the pivot","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"on the opposite side of the pivot, so at the 70 cm mark","field":"all","manual":true}],"solution":"The 70 cm mark\n\nMarker''s note. Follow through from the candidate''s own earlier value. A2 is for realising the weight must go on the other side. An answer of ''20 cm from the pivot'' without identifying the mark earns three of the four.","markerNote":"Follow through from the candidate''s own earlier value. A2 is for realising the weight must go on the other side. An answer of ''20 cm from the pivot'' without identifying the mark earns three of the four.","responseType":null,"answerType":"text"},"phy-p2-2-q2::f":{"answer":"The rule is uniform, so its weight acts at its centre of gravity, which is at the pivot, and its moment about the pivot is therefore zero.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"the weight acts at the centre of the rule, which is at the pivot, so it has no moment","field":"all","manual":true}],"solution":"The rule is uniform, so its weight acts at its centre of gravity, which is at the pivot, and its moment about the pivot is therefore zero.\n\nMarker''s note. Accept ''the perpendicular distance is zero''.","markerNote":"Accept ''the perpendicular distance is zero''.","responseType":null,"answerType":"text"},"phy-p2-2-q3::ai":{"answer":"The specific heat capacity of a substance is the quantity of heat energy required to raise the temperature of 1 kg of the substance by 1 °C.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"heat energy required","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"for unit mass, or for 1 kg","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"to raise the temperature by 1 °C, or by 1 K","field":"all","manual":true}],"solution":"The specific heat capacity of a substance is the quantity of heat energy required to raise the temperature of 1 kg of the substance by 1 °C.\n\nMarker''s note. All three elements are needed. A definition which omits the mass, or which says ''to heat it up'', does not earn the missing mark.","markerNote":"All three elements are needed. A definition which omits the mass, or which says ''to heat it up'', does not earn the missing mark.","responseType":null,"answerType":"text"},"phy-p2-2-q3::aii":{"answer":"The specific latent heat of fusion of a substance is the quantity of heat energy required to change 1 kg of the substance from solid to liquid without any change in temperature.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"heat energy required","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"to change unit mass, or 1 kg, from solid to liquid","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"with no change in temperature","field":"all","manual":true}],"solution":"The specific latent heat of fusion of a substance is the quantity of heat energy required to change 1 kg of the substance from solid to liquid without any change in temperature.\n\nMarker''s note. B3 is the mark most often dropped and cannot be implied.","markerNote":"B3 is the mark most often dropped and cannot be implied.","responseType":null,"answerType":"text"},"phy-p2-2-q3::bi":{"answer":"1.7 × 10⁵ J","modelResponse":"170000 J","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses Q = m l","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 0.50 × 3.4 × 10⁵","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"1.7 × 10⁵ J, with the unit","field":"answer","check":{"type":"value","value":170000,"tolerance":0.02,"unit":"J"}}],"solution":"1.7 × 10⁵ J\n\nMarker''s note. Accept 170 000 J or 170 kJ.","markerNote":"Accept 170 000 J or 170 kJ.","responseType":null,"answerType":"value"},"phy-p2-2-q3::bii":{"answer":"8.4 × 10⁴ J","modelResponse":"84000 J","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses Q = m c Δθ","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 0.50 × 4200 × 40","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"84 000 J, with the unit","field":"answer","check":{"type":"value","value":84000,"tolerance":0.02,"unit":"J"}}],"solution":"8.4 × 10⁴ J\n\nMarker''s note. Using the specific heat capacity of ice here, or a temperature change of 0 °C, loses both M2 and A1.","markerNote":"Using the specific heat capacity of ice here, or a temperature change of 0 °C, loses both M2 and A1.","responseType":null,"answerType":"value"},"phy-p2-2-q3::biii":{"answer":"2.54 × 10⁵ J","modelResponse":"254000 J","criteria":[{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"adds the two answers to give 254 000 J","field":"answer","check":{"type":"value","value":254000,"tolerance":0.02,"unit":"J"}}],"solution":"2.54 × 10⁵ J\n\nMarker''s note. Follow through from the candidate''s own earlier value.","markerNote":"Follow through from the candidate''s own earlier value.","responseType":null,"answerType":"value"},"phy-p2-2-q3::c":{"answer":"It is assumed that no heat energy is transferred to or from the surroundings. In practice the container and the air absorb some energy, so the true energy supplied is greater than calculated.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"states the assumption","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"explains its effect on the answer","field":"all","manual":true}],"solution":"It is assumed that no heat energy is transferred to or from the surroundings. In practice the container and the air absorb some energy, so the true energy supplied is greater than calculated.\n\nMarker''s note. Accept: no energy transferred to the surroundings or the container; the ice is all at exactly 0 °C to begin with; no water evaporates. B2 requires a direction: the calculated value is an underestimate of the energy actually needed.","markerNote":"Accept: no energy transferred to the surroundings or the container; the ice is all at exactly 0 °C to begin with; no water evaporates. B2 requires a direction: the calculated value is an underestimate of the energy actually needed.","responseType":null,"answerType":"text"},"phy-p2-2-q4::a":{"answer":"The angle of incidence equals the angle of reflection. The incident ray, the reflected ray and the normal at the point of incidence all lie in the same plane.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"angle of incidence equals angle of reflection","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"incident ray, reflected ray and normal lie in the same plane","field":"all","manual":true}],"solution":"The angle of incidence equals the angle of reflection. The incident ray, the reflected ray and the normal at the point of incidence all lie in the same plane.\n\nMarker''s note. For B1 the angles must be measured from the normal, but do not withhold the mark unless the candidate says they are measured from the surface.","markerNote":"For B1 the angles must be measured from the normal, but do not withhold the mark unless the candidate says they are measured from the surface.","responseType":null,"answerType":"text"},"phy-p2-2-q4::b":{"answer":"The image is virtual, upright, the same size as the object, laterally inverted, and as far behind the mirror as the object is in front.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"first correct characteristic","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"second correct characteristic","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"third correct characteristic","field":"all","manual":true}],"solution":"The image is virtual, upright, the same size as the object, laterally inverted, and as far behind the mirror as the object is in front.\n\nMarker''s note. Any three of: virtual, upright or erect, same size as the object, laterally inverted, same distance behind the mirror as the object is in front. ''Clear'' and ''the same'' are too vague to score.","markerNote":"Any three of: virtual, upright or erect, same size as the object, laterally inverted, same distance behind the mirror as the object is in front. ''Clear'' and ''the same'' are too vague to score.","responseType":null,"answerType":"text"},"phy-p2-2-q4::c":{"answer":"25.4 degrees","modelResponse":"25.4 °","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses n = sin i ÷ sin r","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"sin r = sin 40 ÷ 1.50 = 0.4285","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"25.4 degrees, accept 25 to 25.5","field":"answer","check":{"type":"value","value":25.4,"tolerance":0.02,"unit":"°"}}],"solution":"25.4 degrees\n\nMarker''s note. Inverting the formula gives 74.6 degrees, which is larger than the angle of incidence and so cannot be right when light enters a denser medium. Award M1 only.","markerNote":"Inverting the formula gives 74.6 degrees, which is larger than the angle of incidence and so cannot be right when light enters a denser medium. Award M1 only.","responseType":null,"answerType":"value"},"phy-p2-2-q4::d":{"answer":"41.8 degrees. A ray striking the surface at a greater angle is totally internally reflected back into the glass.","modelResponse":"41.8 °","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses sin C = 1 ÷ n","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"41.8 degrees, accept 41 to 42","field":"answer","check":{"type":"value","value":41.8,"tolerance":0.02,"unit":"°"}},{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"the ray is totally internally reflected","field":"all","manual":true}],"solution":"41.8 degrees. A ray striking the surface at a greater angle is totally internally reflected back into the glass.\n\nMarker''s note. Follow through from the candidate''s own earlier value. B1 requires the words total internal reflection, or a clear description of the ray being reflected back into the glass with none passing out.","markerNote":"Follow through from the candidate''s own earlier value. B1 requires the words total internal reflection, or a clear description of the ray being reflected back into the glass with none passing out.","responseType":null,"answerType":"value"},"phy-p2-2-q4::e":{"answer":"v = 30 cm, m = 2.0","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses 1/f = 1/u + 1/v","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"1/v = 1/10 − 1/15","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"v = 30 cm, with the unit","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"m = v/u = 2.0, with no unit","field":"all","manual":true}],"solution":"v = 30 cm, m = 2.0\n\nMarker''s note. Follow through from the candidate''s own earlier value. The magnification has no unit; a candidate who gives one loses A2. Accept m calculated as image height ÷ object height if the image height 6.0 cm is found first.","markerNote":"Follow through from the candidate''s own earlier value. The magnification has no unit; a candidate who gives one loses A2. Accept m calculated as image height ÷ object height if the image height 6.0 cm is found first.","responseType":null,"answerType":"text"},"phy-p2-2-q5::a":{"answer":"A magnetic field is the region around a magnet in which a magnetic force can be detected.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"a region, or a space","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"in which a magnetic force acts or can be detected","field":"all","manual":true}],"solution":"A magnetic field is the region around a magnet in which a magnetic force can be detected.\n\nMarker''s note. Both the word region and the word force are needed.","markerNote":"Both the word region and the word force are needed.","responseType":null,"answerType":"text"},"phy-p2-2-q5::b":{"answer":"A permanent magnet keeps its magnetism, and is made from a hard magnetic material such as steel. A temporary magnet loses its magnetism easily, and is made from a soft magnetic material such as iron.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"a permanent magnet retains its magnetism; a temporary one does not","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"steel, or another hard magnetic material, for the permanent magnet","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"soft iron for the temporary magnet","field":"all","manual":true}],"solution":"A permanent magnet keeps its magnetism, and is made from a hard magnetic material such as steel. A temporary magnet loses its magnetism easily, and is made from a soft magnetic material such as iron.\n\nMarker''s note. Accept alnico or any named hard alloy for B2.","markerNote":"Accept alnico or any named hard alloy for B2.","responseType":null,"answerType":"text"},"phy-p2-2-q5::c":{"answer":"Increase the current, increase the number of turns on the coil, and use a soft iron core.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"increase the current","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"increase the number of turns","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"use a soft iron core, or wind the turns more closely","field":"all","manual":true}],"solution":"Increase the current, increase the number of turns on the coil, and use a soft iron core.\n\nMarker''s note. ''Make it bigger'' scores nothing.","markerNote":"''Make it bigger'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-2-q5::di":{"answer":"60 turns","modelResponse":"60","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses Ns/Np = Vs/Vp","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes 1200 × 12 ÷ 240","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"60 turns","field":"answer","check":{"type":"value","value":60,"tolerance":0.02}}],"solution":"60 turns\n\nMarker''s note. The answer is a count of turns and has no unit. A candidate who inverts the ratio obtains 24 000 turns, which is more turns on the secondary of a step down transformer: award M1 only.","markerNote":"The answer is a count of turns and has no unit. A candidate who inverts the ratio obtains 24 000 turns, which is more turns on the secondary of a step down transformer: award M1 only.","responseType":null,"answerType":"value"},"phy-p2-2-q5::dii":{"answer":"0.10 A","modelResponse":"0.1 A","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"power in equals power out: 240 × Ip = 12 × 2.0","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"0.10 A, with the unit","field":"answer","check":{"type":"value","value":0.1,"tolerance":0.02,"unit":"A"}}],"solution":"0.10 A\n\nMarker''s note. Follow through from the candidate''s own earlier value. Accept the turns ratio route, Ip = Is × Ns/Np.","markerNote":"Follow through from the candidate''s own earlier value. Accept the turns ratio route, Ip = Is × Ns/Np.","responseType":null,"answerType":"value"},"phy-p2-2-q5::e":{"answer":"Direct current produces a magnetic field which is steady rather than changing, and a field which does not change induces no voltage in the secondary coil.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"direct current gives a steady, unchanging magnetic field","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"a changing field is needed to induce a voltage, so nothing is induced","field":"all","manual":true}],"solution":"Direct current produces a magnetic field which is steady rather than changing, and a field which does not change induces no voltage in the secondary coil.\n\nMarker''s note. An answer which says only ''it needs a.c.'' restates the question and scores nothing. The word changing is what earns the marks.","markerNote":"An answer which says only ''it needs a.c.'' restates the question and scores nothing. The word changing is what earns the marks.","responseType":null,"answerType":"text"},"phy-p2-2-q6::a":{"answer":"Proton: 1, +1, nucleus. Neutron: 1, 0, nucleus. Electron: 1/1840 (negligible), −1, in shells outside the nucleus.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"proton relative charge +1","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"neutron relative mass 1","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"neutron found in the nucleus","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"KC","description":"electron relative mass negligible, or 1/1840","field":"all","manual":true},{"code":"B5","kind":"B","marks":1,"profile":"KC","description":"electron relative charge −1","field":"all","manual":true},{"code":"B6","kind":"B","marks":1,"profile":"KC","description":"all remaining cells consistent and correct","field":"all","manual":true}],"solution":"Proton: 1, +1, nucleus. Neutron: 1, 0, nucleus. Electron: 1/1840 (negligible), −1, in shells outside the nucleus.\n\nMarker''s note. Accept 0 or ''almost zero'' for the relative mass of the electron.","markerNote":"Accept 0 or ''almost zero'' for the relative mass of the electron.","responseType":"table","answerType":"text"},"phy-p2-2-q6::b":{"answer":"Isotopes are atoms of the same element which have the same number of protons but different numbers of neutrons. Example: carbon-12 and carbon-14.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"same number of protons, different number of neutrons","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"a correct example","field":"all","manual":true}],"solution":"Isotopes are atoms of the same element which have the same number of protons but different numbers of neutrons. Example: carbon-12 and carbon-14.\n\nMarker''s note. Accept ''same atomic number, different mass number''. The example must name two isotopes of the same element, such as carbon-12 and carbon-14, or uranium-235 and uranium-238.","markerNote":"Accept ''same atomic number, different mass number''. The example must name two isotopes of the same element, such as carbon-12 and carbon-14, or uranium-235 and uranium-238.","responseType":null,"answerType":"text"},"phy-p2-2-q6::c":{"answer":"Most alpha particles passed straight through, so the atom is mostly empty space. A few were deflected through large angles, so there is a small, dense, positively charged nucleus.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first observation","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the conclusion drawn from it","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"second, different observation","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"UK","description":"the conclusion drawn from it","field":"all","manual":true}],"solution":"Most alpha particles passed straight through, so the atom is mostly empty space. A few were deflected through large angles, so there is a small, dense, positively charged nucleus.\n\nMarker''s note. Accepted pairs: most passed straight through, so the atom is mostly empty space; a small number were deflected through large angles, so there is a concentrated positive charge; a very few came almost straight back, so the nucleus is small and carries nearly all the mass. A conclusion given without its observation earns the conclusion mark only.","markerNote":"Accepted pairs: most passed straight through, so the atom is mostly empty space; a small number were deflected through large angles, so there is a concentrated positive charge; a very few came almost straight back, so the nucleus is small and carries nearly all the mass. A conclusion given without its observation earns the conclusion mark only.","responseType":null,"answerType":"text"},"phy-p2-2-q6::d":{"answer":"Fission is the splitting of a heavy nucleus into lighter nuclei, and occurs in a nuclear reactor. Fusion is the joining of light nuclei to form a heavier one, and occurs in the Sun and other stars.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"fission: a heavy nucleus splits into lighter ones","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"fusion: light nuclei join to form a heavier one","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"correct location for each: a reactor or an atomic bomb, and the Sun or a star","field":"all","manual":true}],"solution":"Fission is the splitting of a heavy nucleus into lighter nuclei, and occurs in a nuclear reactor. Fusion is the joining of light nuclei to form a heavier one, and occurs in the Sun and other stars.\n\nMarker''s note. Both processes release energy, so that alone does not distinguish them and earns nothing.","markerNote":"Both processes release energy, so that alone does not distinguish them and earns nothing.","responseType":null,"answerType":"text"}}'::jsonb;
begin
 select jsonb_array_length(criteria),
 (select sum((c->>'maxMarks')::integer) from jsonb_array_elements(criteria) c)
 into v_count,v_marks from spark_grading_private.rubrics_v2
 where subject_id='physics' and paper_id='spark-phy-p02-practice-2' and active=false and verification_status='draft';
 if v_count is distinct from 33 or v_marks is distinct from 100
 or (select count(*) from spark_grading_private.rubrics_v2 r
 cross join lateral jsonb_array_elements(r.criteria) c
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-2'
 and v_expected ? (c->>'id')) <> 33
 then raise exception 'Physics/IT exact draft source mismatch for spark-phy-p02-practice-2'; end if;
 update spark_grading_private.rubrics_v2 r set criteria=(
 select jsonb_agg(c || jsonb_build_object('sourceMarking',v_expected->(c->>'id')) order by ordinal)
 from jsonb_array_elements(r.criteria) with ordinality item(c,ordinal))
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-2' and r.active=false and r.verification_status='draft';
end $v2$;
do $v2$ declare v_count integer; v_marks integer; v_expected jsonb:='{"phy-p2-3-q1::a":{"answer":"A straight line through the origin","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"XS","description":"both axes labelled with the quantity and its unit","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"the scales asked for are used, and the points fill at least half the grid","field":"all","manual":true},{"code":"B3","kind":"B","marks":3,"profile":"XS","description":"all six points plotted correctly; deduct one mark for each point misplaced","field":"all","manual":true},{"code":"B4","kind":"B","marks":2,"profile":"XS","description":"a single best fit straight line drawn, passing close to the origin","field":"all","manual":true}],"solution":"A straight line through the origin\n\nMarker''s note. The points carry a little scatter, which is deliberate. A candidate who joins them dot to dot scores nothing for B4.","markerNote":"The points carry a little scatter, which is deliberate. A candidate who joins them dot to dot scores nothing for B4.","responseType":"graph","answerType":"text"},"phy-p2-3-q1::b":{"answer":"gradient = 5.0 Ω","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":2,"profile":"XS","description":"a triangle drawn on the line, using at least half its length","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"XS","description":"gradient in the range 4.7 to 5.3","field":"all","manual":true},{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the unit, ohms, V A⁻¹ or V/A","field":"all","manual":true}],"solution":"gradient = 5.0 Ω\n\nMarker''s note. Plotting the axes the other way round gives a gradient of about 0.20 A V⁻¹, which is the conductance. Award M1 and B1 if the unit matches the axes used, but withhold A1 unless the candidate identifies the quantity correctly in Part (c).","markerNote":"Plotting the axes the other way round gives a gradient of about 0.20 A V⁻¹, which is the conductance. Award M1 and B1 if the unit matches the axes used, but withhold A1 unless the candidate identifies the quantity correctly in Part (c).","responseType":null,"answerType":"text"},"phy-p2-3-q1::c":{"answer":"The resistance of the wire","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"resistance","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"of the wire, and consistent with the gradient found in Part (b)","field":"all","manual":true}],"solution":"The resistance of the wire\n\nMarker''s note. Follow through from the candidate''s own earlier value.","markerNote":"Follow through from the candidate''s own earlier value.","responseType":null,"answerType":"text"},"phy-p2-3-q1::d":{"answer":"The current through a metallic conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions remain constant. The graph is a straight line through the origin, which is what proportionality means.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"current proportional to potential difference","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"provided the temperature stays constant","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"the straight line through the origin shows the proportionality","field":"all","manual":true}],"solution":"The current through a metallic conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions remain constant. The graph is a straight line through the origin, which is what proportionality means.\n\nMarker''s note. For B3 a straight line alone is not enough: the candidate must say it passes through the origin, since a straight line with an intercept is not proportionality.","markerNote":"For B3 a straight line alone is not enough: the candidate must say it passes through the origin, since a straight line with an intercept is not proportionality.","responseType":null,"answerType":"text"},"phy-p2-3-q1::e":{"answer":"0.35 A","modelResponse":"0.35 A","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"XS","description":"reads across from 1.75 V on the vertical axis to the line","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"XS","description":"reads down to the horizontal axis","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"0.35 A, accept 0.33 to 0.37 A","field":"answer","check":{"type":"value","value":0.35,"tolerance":0.02,"unit":"A"}}],"solution":"0.35 A\n\nMarker''s note. Show of construction lines on the graph is acceptable evidence for M1 and M2. A candidate who calculates 1.75 ÷ 5.0 has not used the graph as asked: award A1 and one method mark.","markerNote":"Show of construction lines on the graph is acceptable evidence for M1 and M2. A candidate who calculates 1.75 ÷ 5.0 has not used the graph as asked: award A1 and one method mark.","responseType":null,"answerType":"value"},"phy-p2-3-q1::f":{"answer":"The line would still be straight and pass through the origin, but it would be steeper, because doubling the length doubles the resistance.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"still a straight line through the origin","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"steeper, or a larger gradient","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"because the resistance is doubled, resistance being proportional to length","field":"all","manual":true}],"solution":"The line would still be straight and pass through the origin, but it would be steeper, because doubling the length doubles the resistance.\n\nMarker''s note. A candidate who says the line is less steep has the relationship inverted: award B1 only. If the candidate plotted I against V in Part (a), a less steep line is correct and B2 should be awarded.","markerNote":"A candidate who says the line is less steep has the relationship inverted: award B1 only. If the candidate plotted I against V in Part (a), a less steep line is correct and B2 should be awarded.","responseType":null,"answerType":"text"},"phy-p2-3-q1::g":{"answer":"Keep the switch open between readings so the wire does not warm up, and check both meters for a zero error before starting.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"XS","description":"first precaution with the reason it matters","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"second, different precaution","field":"all","manual":true}],"solution":"Keep the switch open between readings so the wire does not warm up, and check both meters for a zero error before starting.\n\nMarker''s note. Accept: switch off between readings, since a warmer wire has a greater resistance; check for zero error; tighten every connection; keep the wire straight; read the meters square on to avoid parallax. Refuse ''avoid human error'' and ''be accurate''.","markerNote":"Accept: switch off between readings, since a warmer wire has a greater resistance; check for zero error; tighten every connection; keep the wire straight; read the meters square on to avoid parallax. Refuse ''avoid human error'' and ''be accurate''.","responseType":null,"answerType":"text"},"phy-p2-3-q2::a":{"answer":"Acceleration is the rate of change of velocity. Its SI unit is m s⁻².","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"rate of change of velocity","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"m s⁻²","field":"all","manual":true}],"solution":"Acceleration is the rate of change of velocity. Its SI unit is m s⁻².\n\nMarker''s note. ''Change of velocity'' without ''rate of'' does not earn B1. Do not accept ''rate of change of speed'', since acceleration is a vector.","markerNote":"''Change of velocity'' without ''rate of'' does not earn B1. Do not accept ''rate of change of speed'', since acceleration is a vector.","responseType":null,"answerType":"text"},"phy-p2-3-q2::b":{"answer":"2.5 m s⁻²","modelResponse":"2.5 m s⁻²","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses a = (v − u) ÷ t with u = 0","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"2.5 m s⁻², with the unit","field":"answer","check":{"type":"value","value":2.5,"tolerance":0.02,"unit":"m s⁻²"}}],"solution":"2.5 m s⁻²","markerNote":null,"responseType":null,"answerType":"value"},"phy-p2-3-q2::c":{"answer":"3000 N","modelResponse":"3000 N","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses F = ma","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"3000 N, with the unit","field":"answer","check":{"type":"value","value":3000,"tolerance":0.02,"unit":"N"}}],"solution":"3000 N\n\nMarker''s note. Follow through from the candidate''s own earlier value. Accept 3.0 × 10³ N or 3.0 kN.","markerNote":"Follow through from the candidate''s own earlier value. Accept 3.0 × 10³ N or 3.0 kN.","responseType":null,"answerType":"value"},"phy-p2-3-q2::d":{"answer":"687.5 m","modelResponse":"687.5 m","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"XS","description":"recognises that the distance is the area under a velocity-time graph, or splits the journey into three stages","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"accelerating stage: ½ × 10 × 25 = 125 m","field":"all","manual":true},{"code":"M3","kind":"M","marks":1,"profile":"UK","description":"constant speed stage: 25 × 20 = 500 m; braking stage: ½ × 5.0 × 25 = 62.5 m","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"687.5 m, with the unit","field":"answer","check":{"type":"value","value":687.5,"tolerance":0.02,"unit":"m"}}],"solution":"687.5 m\n\nMarker''s note. Accept 690 m or 6.9 × 10² m. Omitting the halves on the two triangular stages gives 1000 m: award M1 only. This is the commonest error in the question.","markerNote":"Accept 690 m or 6.9 × 10² m. Omitting the halves on the two triangular stages gives 1000 m: award M1 only. This is the commonest error in the question.","responseType":null,"answerType":"value"},"phy-p2-3-q2::e":{"answer":"A body remains at rest, or continues to move with constant velocity in a straight line, unless acted upon by an unbalanced force. When the car brakes, the braking force acts on the car and not on the passenger, so the passenger continues to move forward at the original speed.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"states the law, including the condition of an unbalanced or resultant force","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the braking force acts on the car, not on the passenger","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"so the passenger continues to move forward at the original speed","field":"all","manual":true}],"solution":"A body remains at rest, or continues to move with constant velocity in a straight line, unless acted upon by an unbalanced force. When the car brakes, the braking force acts on the car and not on the passenger, so the passenger continues to move forward at the original speed.\n\nMarker''s note. An answer which says the passenger is ''thrown forward by a force'' has the physics backwards: no forward force acts, which is the point of the question. Award B1 only.","markerNote":"An answer which says the passenger is ''thrown forward by a force'' has the physics backwards: no forward force acts, which is the point of the question. Award B1 only.","responseType":null,"answerType":"text"},"phy-p2-3-q2::f":{"answer":"3.0 × 10⁴ kg m s⁻¹","modelResponse":"30000 kg m s⁻¹","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses p = mv","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"30 000 kg m s⁻¹, with the unit","field":"answer","check":{"type":"value","value":30000,"tolerance":0.02,"unit":"kg m s⁻¹"}}],"solution":"3.0 × 10⁴ kg m s⁻¹\n\nMarker''s note. Accept N s as the unit.","markerNote":"Accept N s as the unit.","responseType":null,"answerType":"value"},"phy-p2-3-q3::a":{"answer":"Solid: very close, regular, vibrate about fixed positions. Liquid: close together, irregular, move about at random over short distances. Gas: far apart, random, move rapidly in all directions.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"solid: regular arrangement","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"solid: vibrate about fixed positions","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"liquid: close together","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"UK","description":"liquid: slide past one another, or move at random over short distances","field":"all","manual":true},{"code":"B5","kind":"B","marks":1,"profile":"UK","description":"gas: far apart","field":"all","manual":true},{"code":"B6","kind":"B","marks":1,"profile":"UK","description":"gas: random or irregular arrangement","field":"all","manual":true}],"solution":"Solid: very close, regular, vibrate about fixed positions. Liquid: close together, irregular, move about at random over short distances. Gas: far apart, random, move rapidly in all directions.\n\nMarker''s note. Accept ''touching'' for the spacing in a liquid. Do not accept ''the particles get bigger'' anywhere in the table.","markerNote":"Accept ''touching'' for the spacing in a liquid. Do not accept ''the particles get bigger'' anywhere in the table.","responseType":"table","answerType":"text"},"phy-p2-3-q3::b":{"answer":"The particles move rapidly in all directions and collide with the walls of the container. Each collision changes the momentum of a particle, so the wall exerts a force on it and it exerts an equal force back on the wall. The total force over the area of the wall is the pressure.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"the particles collide with the walls","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"each collision exerts a force on the wall, through a change of momentum","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"the force per unit area of wall is the pressure","field":"all","manual":true}],"solution":"The particles move rapidly in all directions and collide with the walls of the container. Each collision changes the momentum of a particle, so the wall exerts a force on it and it exerts an equal force back on the wall. The total force over the area of the wall is the pressure.\n\nMarker''s note. An answer which says only ''the particles push on the walls'' earns B1 alone.","markerNote":"An answer which says only ''the particles push on the walls'' earns B1 alone.","responseType":null,"answerType":"text"},"phy-p2-3-q3::c":{"answer":"133 kPa","modelResponse":"133 kPa","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"converts both temperatures to kelvin: 300 K and 400 K","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"uses P₁/T₁ = P₂/T₂ at constant volume","field":"all","manual":true},{"code":"M3","kind":"M","marks":1,"profile":"UK","description":"substitutes 100 × 400 ÷ 300","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"133 kPa, with the unit","field":"answer","check":{"type":"value","value":133,"tolerance":0.02,"unit":"kPa"}}],"solution":"133 kPa\n\nMarker''s note. Working in degrees Celsius gives 470 kPa. This loses M1 and A1 but keeps M2. Accept 1.33 × 10⁵ Pa.","markerNote":"Working in degrees Celsius gives 470 kPa. This loses M1 and A1 but keeps M2. Accept 1.33 × 10⁵ Pa.","responseType":null,"answerType":"value"},"phy-p2-3-q3::d":{"answer":"Gaps are left between the sections of a bridge or a railway line, and overhead cables are hung with a sag.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first genuine allowance","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"second, different allowance","field":"all","manual":true}],"solution":"Gaps are left between the sections of a bridge or a railway line, and overhead cables are hung with a sag.\n\nMarker''s note. Accept: expansion gaps in bridges, railway lines or concrete roads; rollers under one end of a bridge; sagging overhead cables; loops in pipelines; a gap at the end of a run of guttering.","markerNote":"Accept: expansion gaps in bridges, railway lines or concrete roads; rollers under one end of a bridge; sagging overhead cables; loops in pipelines; a gap at the end of a run of guttering.","responseType":null,"answerType":"text"},"phy-p2-3-q4::a":{"answer":"They are all transverse waves, they all travel at 3.0 × 10⁸ m s⁻¹ in a vacuum, and they can all travel through a vacuum.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"transverse","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"travel at the same speed in a vacuum, 3.0 × 10⁸ m s⁻¹","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"can travel through a vacuum, or carry no charge, or can be reflected and refracted","field":"all","manual":true}],"solution":"They are all transverse waves, they all travel at 3.0 × 10⁸ m s⁻¹ in a vacuum, and they can all travel through a vacuum.\n\nMarker''s note. Accept ''they are all electromagnetic waves'' for nothing, since it restates the question.","markerNote":"Accept ''they are all electromagnetic waves'' for nothing, since it restates the question.","responseType":null,"answerType":"text"},"phy-p2-3-q4::b":{"answer":"X-rays, ultraviolet, infrared, microwaves","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"X-rays first","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"ultraviolet second","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"infrared then microwaves","field":"all","manual":true}],"solution":"X-rays, ultraviolet, infrared, microwaves\n\nMarker''s note. A completely reversed list shows knowledge of the order but answers the opposite question: award one mark only.","markerNote":"A completely reversed list shows knowledge of the order but answers the opposite question: award one mark only.","responseType":null,"answerType":"text"},"phy-p2-3-q4::c":{"answer":"1.0 × 10⁶ Hz","modelResponse":"1000000 Hz","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses c = f λ","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"f = 3.0 × 10⁸ ÷ 300","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"1.0 × 10⁶ Hz, with the unit","field":"answer","check":{"type":"value","value":1000000,"tolerance":0.02,"unit":"Hz"}}],"solution":"1.0 × 10⁶ Hz\n\nMarker''s note. Accept 1 MHz or 1000 kHz.","markerNote":"Accept 1 MHz or 1000 kHz.","responseType":null,"answerType":"value"},"phy-p2-3-q4::d":{"answer":"Use: sterilising equipment, or detecting forged banknotes. Hazard: it damages the skin and can cause skin cancer, and it damages the eyes.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"a correct use","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"a correct hazard","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"either use or hazard given with some detail of how or why","field":"all","manual":true}],"solution":"Use: sterilising equipment, or detecting forged banknotes. Hazard: it damages the skin and can cause skin cancer, and it damages the eyes.\n\nMarker''s note. Uses: sterilising, security marking, detecting forgeries, producing vitamin D, fluorescent lamps, sun tanning. Hazards: sunburn, skin cancer, damage to the retina, premature ageing of the skin.","markerNote":"Uses: sterilising, security marking, detecting forgeries, producing vitamin D, fluorescent lamps, sun tanning. Hazards: sunburn, skin cancer, damage to the retina, premature ageing of the skin.","responseType":null,"answerType":"text"},"phy-p2-3-q4::e":{"answer":"Diffraction is the spreading out of a wave as it passes through a gap or round an obstacle. It is not normally observed with light because the wavelength of light is very small, about 5 × 10⁻⁷ m, and everyday gaps are enormous by comparison.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"spreading of a wave at a gap or an edge","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"noticeable diffraction needs a gap comparable with the wavelength","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"the wavelength of light is far smaller than everyday gaps","field":"all","manual":true}],"solution":"Diffraction is the spreading out of a wave as it passes through a gap or round an obstacle. It is not normally observed with light because the wavelength of light is very small, about 5 × 10⁻⁷ m, and everyday gaps are enormous by comparison.\n\nMarker''s note. An answer which says only ''light travels in straight lines'' scores nothing, since that is the observation to be explained rather than the explanation.","markerNote":"An answer which says only ''light travels in straight lines'' scores nothing, since that is the observation to be explained rather than the explanation.","responseType":null,"answerType":"text"},"phy-p2-3-q5::a":{"answer":"AND: 0, 0, 0, 1. OR: 0, 1, 1, 1.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"AND gives 0 for inputs 0 and 1","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"AND gives 0 for inputs 1 and 0","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"AND gives 1 for inputs 1 and 1","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"KC","description":"OR gives 1 for inputs 0 and 1","field":"all","manual":true},{"code":"B5","kind":"B","marks":1,"profile":"KC","description":"OR gives 1 for inputs 1 and 0","field":"all","manual":true},{"code":"B6","kind":"B","marks":1,"profile":"KC","description":"OR gives 1 for inputs 1 and 1","field":"all","manual":true}],"solution":"AND: 0, 0, 0, 1. OR: 0, 1, 1, 1.\n\nMarker''s note. Accept the outputs written as high and low, or as 1 and 0, provided the candidate is consistent.","markerNote":"Accept the outputs written as high and low, or as 1 and 0, provided the candidate is consistent.","responseType":"table","answerType":"text"},"phy-p2-3-q5::b":{"answer":"1, 1, 1, 0","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"output 1 for inputs 0 and 0","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"output 1 for inputs 0 and 1","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"output 1 for inputs 1 and 0","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"UK","description":"output 0 for inputs 1 and 1","field":"all","manual":true}],"solution":"1, 1, 1, 0\n\nMarker''s note. This is the NAND truth table, the inverse of the AND column in Part (a). Follow through from the candidate''s own earlier value. A candidate whose AND column was wrong but who inverts it correctly earns full marks here.","markerNote":"This is the NAND truth table, the inverse of the AND column in Part (a). Follow through from the candidate''s own earlier value. A candidate whose AND column was wrong but who inverts it correctly earns full marks here.","responseType":"table","answerType":"text"},"phy-p2-3-q5::c":{"answer":"The diode conducts only when it is forward biased, so current flows during one half of each cycle and is blocked during the other half. The output is a series of pulses in one direction only.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"the diode conducts in one direction only","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"current flows during one half of the cycle and is blocked during the other","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"the output is in one direction only, so it is direct current, though it varies","field":"all","manual":true}],"solution":"The diode conducts only when it is forward biased, so current flows during one half of each cycle and is blocked during the other half. The output is a series of pulses in one direction only.\n\nMarker''s note. A labelled sketch showing the input and output waveforms may earn B2 and B3 without words.","markerNote":"A labelled sketch showing the input and output waveforms may earn B2 and B3 without words.","responseType":null,"answerType":"text"},"phy-p2-3-q5::d":{"answer":"Direct current from a battery is a horizontal straight line at a steady value. Half wave rectified alternating current is a series of humps above the axis with gaps between them, all on the same side of the axis.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"battery: a steady, constant value, a horizontal line","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"rectified a.c.: varies, but stays on one side of the axis","field":"all","manual":true}],"solution":"Direct current from a battery is a horizontal straight line at a steady value. Half wave rectified alternating current is a series of humps above the axis with gaps between them, all on the same side of the axis.\n\nMarker''s note. Descriptions or sketches are equally acceptable.","markerNote":"Descriptions or sketches are equally acceptable.","responseType":null,"answerType":"text"},"phy-p2-3-q6::a":{"answer":"In fission a heavy nucleus splits into two lighter nuclei of roughly equal mass, together with neutrons, releasing energy. In fusion two light nuclei join to form a heavier nucleus, releasing energy. Fission is used in nuclear reactors; fusion is the source of the Sun''s energy.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"fission: a heavy nucleus splits","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"fission: into two lighter nuclei, with neutrons released","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"fusion: light nuclei join to form a heavier one","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"KC","description":"fusion requires extremely high temperature and pressure, or occurs in stars","field":"all","manual":true}],"solution":"In fission a heavy nucleus splits into two lighter nuclei of roughly equal mass, together with neutrons, releasing energy. In fusion two light nuclei join to form a heavier nucleus, releasing energy. Fission is used in nuclear reactors; fusion is the source of the Sun''s energy.\n\nMarker''s note. Saying that both release energy earns nothing on its own, since it does not distinguish them.","markerNote":"Saying that both release energy earns nothing on its own, since it does not distinguish them.","responseType":null,"answerType":"text"},"phy-p2-3-q6::b":{"answer":"The mass number of radon is 222 and its atomic number is 86.","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"mass numbers balance: 226 = 222 + 4","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"222","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"86","field":"all","manual":true}],"solution":"The mass number of radon is 222 and its atomic number is 86.\n\nMarker''s note. A candidate who writes 224 and 86, or 222 and 84, has balanced only one of the two: award M1 and one A mark.","markerNote":"A candidate who writes 224 and 86, or 222 and 84, has balanced only one of the two: award M1 and one A mark.","responseType":null,"answerType":"text"},"phy-p2-3-q6::c":{"answer":"It can kill or damage living cells, and it can cause mutations in cells which may lead to cancer.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first harmful effect","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"second, different harmful effect","field":"all","manual":true}],"solution":"It can kill or damage living cells, and it can cause mutations in cells which may lead to cancer.\n\nMarker''s note. Accept: kills cells, causes burns, causes mutations, causes cancer, causes radiation sickness, damages a developing foetus, causes sterility. ''It is dangerous'' scores nothing.","markerNote":"Accept: kills cells, causes burns, causes mutations, causes cancer, causes radiation sickness, damages a developing foetus, causes sterility. ''It is dangerous'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-3-q6::d":{"answer":"Advantages: no carbon dioxide or sulphur dioxide is produced during generation, and a small mass of fuel yields an enormous amount of energy. Disadvantages: the waste stays dangerously radioactive for thousands of years, and an accident at the station could release radioactive material over a wide area.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first advantage","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"second, different advantage","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"first disadvantage","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"UK","description":"second, different disadvantage","field":"all","manual":true}],"solution":"Advantages: no carbon dioxide or sulphur dioxide is produced during generation, and a small mass of fuel yields an enormous amount of energy. Disadvantages: the waste stays dangerously radioactive for thousands of years, and an accident at the station could release radioactive material over a wide area.\n\nMarker''s note. Advantages: no greenhouse gases or acid rain from generation, very high energy density, fuel reserves last longer than fossil fuel reserves, output does not depend on the weather. Disadvantages: radioactive waste and its long term storage, the risk and consequence of an accident, high cost of building and of decommissioning, the link to weapons material. Two versions of the same point score once.","markerNote":"Advantages: no greenhouse gases or acid rain from generation, very high energy density, fuel reserves last longer than fossil fuel reserves, output does not depend on the weather. Disadvantages: radioactive waste and its long term storage, the risk and consequence of an accident, high cost of building and of decommissioning, the link to weapons material. Two versions of the same point score once.","responseType":null,"answerType":"text"},"phy-p2-3-q6::e":{"answer":"Treating cancer with gamma radiation, and using a tracer to find a leak in an underground pipe.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"first use","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"second, different use","field":"all","manual":true}],"solution":"Treating cancer with gamma radiation, and using a tracer to find a leak in an underground pipe.\n\nMarker''s note. Accept: radiotherapy, medical tracers, sterilising surgical instruments and food, carbon dating, dating rocks, thickness gauging in a factory, detecting leaks, smoke alarms. The question excludes generating electricity.","markerNote":"Accept: radiotherapy, medical tracers, sterilising surgical instruments and food, carbon dating, dating rocks, thickness gauging in a factory, detecting leaks, smoke alarms. The question excludes generating electricity.","responseType":null,"answerType":"text"}}'::jsonb;
begin
 select jsonb_array_length(criteria),
 (select sum((c->>'maxMarks')::integer) from jsonb_array_elements(criteria) c)
 into v_count,v_marks from spark_grading_private.rubrics_v2
 where subject_id='physics' and paper_id='spark-phy-p02-practice-3' and active=false and verification_status='draft';
 if v_count is distinct from 31 or v_marks is distinct from 100
 or (select count(*) from spark_grading_private.rubrics_v2 r
 cross join lateral jsonb_array_elements(r.criteria) c
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-3'
 and v_expected ? (c->>'id')) <> 31
 then raise exception 'Physics/IT exact draft source mismatch for spark-phy-p02-practice-3'; end if;
 update spark_grading_private.rubrics_v2 r set criteria=(
 select jsonb_agg(c || jsonb_build_object('sourceMarking',v_expected->(c->>'id')) order by ordinal)
 from jsonb_array_elements(r.criteria) with ordinality item(c,ordinal))
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-3' and r.active=false and r.verification_status='draft';
end $v2$;
do $v2$ declare v_count integer; v_marks integer; v_expected jsonb:='{"phy-p2-4-q1::a":{"answer":"0.40 N at 40.0 cm³, 0.80 N at 80.0 cm³ and 1.00 N at 100.0 cm³","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":2,"profile":"UK","description":"subtracts the spring balance reading from the weight in air, U = 2.00 − R","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"0.40 N","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"0.80 N","field":"all","manual":true},{"code":"A3","kind":"A","marks":1,"profile":"UK","description":"1.00 N","field":"all","manual":true}],"solution":"0.40 N at 40.0 cm³, 0.80 N at 80.0 cm³ and 1.00 N at 100.0 cm³\n\nMarker''s note. Every value in the column must be quoted to the same number of decimal places, so 0.4 rather than 0.40 loses nothing here but would lose the recording mark in the School-Based Assessment. A candidate who adds instead of subtracting gets 3.60, 2.80 and 3.00 and loses M1 and every A mark.","markerNote":"Every value in the column must be quoted to the same number of decimal places, so 0.4 rather than 0.40 loses nothing here but would lose the recording mark in the School-Based Assessment. A candidate who adds instead of subtracting gets 3.60, 2.80 and 3.00 and loses M1 and every A mark.","responseType":"table","answerType":"text"},"phy-p2-4-q1::b":{"answer":"A straight line through the origin","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"XS","description":"both axes labelled with the quantity and its unit","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"XS","description":"the scales asked for are used, and the points fill at least half the grid","field":"all","manual":true},{"code":"B3","kind":"B","marks":3,"profile":"XS","description":"all five points plotted correctly; deduct one mark for each point misplaced","field":"all","manual":true},{"code":"B4","kind":"B","marks":2,"profile":"XS","description":"a single best fit straight line drawn through the points and the origin","field":"all","manual":true}],"solution":"A straight line through the origin\n\nMarker''s note. The line must pass through the origin: no volume submerged means no upthrust. A line drawn with a ruler which misses the origin still scores B4 if the plotted points justify it, but a dot to dot line scores nothing.","markerNote":"The line must pass through the origin: no volume submerged means no upthrust. A line drawn with a ruler which misses the origin still scores B4 if the plotted points justify it, but a dot to dot line scores nothing.","responseType":"graph","answerType":"text"},"phy-p2-4-q1::c":{"answer":"gradient = 0.0100 N cm⁻³","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":2,"profile":"XS","description":"a triangle drawn on the line, using at least half its length","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"XS","description":"gradient in the range 0.0095 to 0.0105","field":"all","manual":true},{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"the unit N cm⁻³","field":"all","manual":true}],"solution":"gradient = 0.0100 N cm⁻³\n\nMarker''s note. Accept N/cm³. A gradient read from two of the table values rather than from the drawn line loses M1 but may still earn A1. Accept 1.0 × 10⁻² N cm⁻³.","markerNote":"Accept N/cm³. A gradient read from two of the table values rather than from the drawn line loses M1 but may still earn A1. Accept 1.0 × 10⁻² N cm⁻³.","responseType":null,"answerType":"text"},"phy-p2-4-q1::d":{"answer":"1000 kg m⁻³","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"XS","description":"identifies the gradient as ρg","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"XS","description":"converts the gradient to N m⁻³: 0.0100 ÷ 1 × 10⁻⁶ = 1.0 × 10⁴","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"divides by g: 1.0 × 10⁴ ÷ 10","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"1000 kg m⁻³, with the unit","field":"all","manual":true}],"solution":"1000 kg m⁻³\n\nMarker''s note. Follow through from the candidate''s own earlier value. The conversion in M2 is the step this part is built to test, and the commonest error is to omit it and answer 0.001 kg m⁻³. Award M1 only in that case. Accept 1.0 × 10³ kg m⁻³, and accept 1 g cm⁻³ if the unit is given.","markerNote":"Follow through from the candidate''s own earlier value. The conversion in M2 is the step this part is built to test, and the commonest error is to omit it and answer 0.001 kg m⁻³. Award M1 only in that case. Accept 1.0 × 10³ kg m⁻³, and accept 1 g cm⁻³ if the unit is given.","responseType":null,"answerType":"text"},"phy-p2-4-q1::e":{"answer":"Archimedes'' principle states that when a body is wholly or partly immersed in a fluid, the upthrust on it equals the weight of the fluid it displaces. As more of the cylinder went below the surface it displaced more water, so the upthrust grew, and the spring balance supported less of the cylinder''s weight.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"KC","description":"the principle, including that the upthrust equals the weight of fluid displaced","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"links the greater volume displaced to the greater upthrust and the smaller reading","field":"all","manual":true}],"solution":"Archimedes'' principle states that when a body is wholly or partly immersed in a fluid, the upthrust on it equals the weight of the fluid it displaces. As more of the cylinder went below the surface it displaced more water, so the upthrust grew, and the spring balance supported less of the cylinder''s weight.\n\nMarker''s note. B1 requires the words weight of fluid displaced. ''The upthrust equals the volume displaced'' is dimensionally wrong and scores nothing. For B2 accept any answer which says the upthrust increased, so the balance had less to support.","markerNote":"B1 requires the words weight of fluid displaced. ''The upthrust equals the volume displaced'' is dimensionally wrong and scores nothing. For B2 accept any answer which says the upthrust increased, so the balance had less to support.","responseType":null,"answerType":"text"},"phy-p2-4-q1::f":{"answer":"Make sure the cylinder does not touch the sides or the bottom of the beaker, because that would support part of its weight and make the reading too small.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"XS","description":"one specific precaution, with the reason it matters","field":"all","manual":true}],"solution":"Make sure the cylinder does not touch the sides or the bottom of the beaker, because that would support part of its weight and make the reading too small.\n\nMarker''s note. Accept: the cylinder must not touch the beaker; read the spring balance square on to avoid parallax; check the balance for a zero error before starting; wait for the balance to come to rest before reading it; keep the water level steady. Award one mark where the precaution is named without a reason. An answer that blames the person rather than naming the error scores nothing.","markerNote":"Accept: the cylinder must not touch the beaker; read the spring balance square on to avoid parallax; check the balance for a zero error before starting; wait for the balance to come to rest before reading it; keep the water level steady. Award one mark where the precaution is named without a reason. An answer that blames the person rather than naming the error scores nothing.","responseType":null,"answerType":"text"},"phy-p2-4-q2::a":{"answer":"A scalar has magnitude only; a vector has both magnitude and direction. Examples: mass or speed; force or velocity.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"scalar has magnitude only","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"vector has magnitude and direction","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"one correct example of each","field":"all","manual":true}],"solution":"A scalar has magnitude only; a vector has both magnitude and direction. Examples: mass or speed; force or velocity.\n\nMarker''s note. Accept for scalars: mass, distance, speed, time, energy, temperature, density. For vectors: force, weight, velocity, acceleration, displacement, momentum. A candidate who offers speed as a vector or velocity as a scalar loses B3.","markerNote":"Accept for scalars: mass, distance, speed, time, energy, temperature, density. For vectors: force, weight, velocity, acceleration, displacement, momentum. A candidate who offers speed as a vector or velocity as a scalar loses B3.","responseType":null,"answerType":"text"},"phy-p2-4-q2::b":{"answer":"10.0 N","modelResponse":"10 N","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"recognises the two forces are at right angles and uses Pythagoras","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes √(8.0² + 6.0²)","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"10.0 N, with the unit","field":"answer","check":{"type":"value","value":10,"tolerance":0.02,"unit":"N"}}],"solution":"10.0 N\n\nMarker''s note. Adding the forces to give 14 N ignores the directions and scores nothing. A scale drawing which produces 10 N earns all three marks provided the scale is stated.","markerNote":"Adding the forces to give 14 N ignores the directions and scores nothing. A scale drawing which produces 10 N earns all three marks provided the scale is stated.","responseType":null,"answerType":"value"},"phy-p2-4-q2::c":{"answer":"36.9 degrees east of north","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses a trigonometric ratio with the correct pair of sides","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"tan θ = 6.0 ÷ 8.0","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"36.9 degrees, measured from north towards the east","field":"all","manual":true}],"solution":"36.9 degrees east of north\n\nMarker''s note. Follow through from the candidate''s own earlier value. Accept 37 degrees. An answer of 53.1 degrees has been measured from the east instead of from the north: award M1 and M2, and award A1 only if the candidate states clearly that the angle is measured from east. A bearing of 037 is acceptable.","markerNote":"Follow through from the candidate''s own earlier value. Accept 37 degrees. An answer of 53.1 degrees has been measured from the east instead of from the north: award M1 and M2, and award A1 only if the candidate states clearly that the angle is measured from east. A bearing of 037 is acceptable.","responseType":null,"answerType":"text"},"phy-p2-4-q2::di":{"answer":"8.0 N","modelResponse":"8 N","criteria":[{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"8.0 N","field":"answer","check":{"type":"value","value":8,"tolerance":0.02,"unit":"N"}}],"solution":"8.0 N","markerNote":null,"responseType":null,"answerType":"value"},"phy-p2-4-q2::dii":{"answer":"2.0 N","modelResponse":"2 N","criteria":[{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"2.0 N","field":"answer","check":{"type":"value","value":2,"tolerance":0.02,"unit":"N"}}],"solution":"2.0 N\n\nMarker''s note. Accept 2.0 N in the direction of the 5.0 N force.","markerNote":"Accept 2.0 N in the direction of the 5.0 N force.","responseType":null,"answerType":"value"},"phy-p2-4-q2::e":{"answer":"A body is in equilibrium when it is at rest, or moving with constant velocity, so that it has no acceleration. The resultant force on it must be zero, and the sum of the clockwise moments about any point must equal the sum of the anticlockwise moments about that point.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"KC","description":"explains equilibrium as at rest or moving at constant velocity, with no acceleration","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"the resultant force is zero","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"the resultant moment about any point is zero","field":"all","manual":true}],"solution":"A body is in equilibrium when it is at rest, or moving with constant velocity, so that it has no acceleration. The resultant force on it must be zero, and the sum of the clockwise moments about any point must equal the sum of the anticlockwise moments about that point.\n\nMarker''s note. A candidate who says only ''the forces are balanced'' has given B2 in other words and earns that mark alone. Both conditions are needed: a body acted on by two equal and opposite forces along different lines has no resultant force but does rotate, so it is not in equilibrium.","markerNote":"A candidate who says only ''the forces are balanced'' has given B2 in other words and earns that mark alone. Both conditions are needed: a body acted on by two equal and opposite forces along different lines has no resultant force but does rotate, so it is not in equilibrium.","responseType":null,"answerType":"text"},"phy-p2-4-q3::a":{"answer":"The volume of a liquid, used in a liquid-in-glass thermometer, and the resistance of a wire, used in a resistance thermometer.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"first property that varies with temperature","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"second, different property","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"a thermometer correctly paired with one of them","field":"all","manual":true}],"solution":"The volume of a liquid, used in a liquid-in-glass thermometer, and the resistance of a wire, used in a resistance thermometer.\n\nMarker''s note. Accept: the volume of a liquid, the resistance of a metal, the electromotive force of a thermocouple, the pressure of a fixed mass of gas at constant volume, the colour of a hot body. The pairing must be right: naming resistance and then saying liquid-in-glass loses B3.","markerNote":"Accept: the volume of a liquid, the resistance of a metal, the electromotive force of a thermocouple, the pressure of a fixed mass of gas at constant volume, the colour of a hot body. The pairing must be right: naming resistance and then saying liquid-in-glass loses B3.","responseType":null,"answerType":"text"},"phy-p2-4-q3::b":{"answer":"The ice point is the temperature of pure melting ice at normal atmospheric pressure. The steam point is the temperature of steam above water boiling at normal atmospheric pressure.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"ice point: pure melting ice","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"steam point: steam above boiling water, not the water itself","field":"all","manual":true}],"solution":"The ice point is the temperature of pure melting ice at normal atmospheric pressure. The steam point is the temperature of steam above water boiling at normal atmospheric pressure.\n\nMarker''s note. The mention of standard atmospheric pressure is not required for either mark, but ''the temperature of boiling water'' rather than of the steam above it loses B2, because dissolved impurities raise the temperature of the water and not that of the steam.","markerNote":"The mention of standard atmospheric pressure is not required for either mark, but ''the temperature of boiling water'' rather than of the steam above it loses B2, because dissolved impurities raise the temperature of the water and not that of the steam.","responseType":null,"answerType":"text"},"phy-p2-4-q3::c":{"answer":"35 °C","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"uses θ = (l − l₀) ÷ (l₁₀₀ − l₀) × 100","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"substitutes (9.0 − 2.0) ÷ (22.0 − 2.0)","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"evaluates the fraction as 7.0 ÷ 20.0 = 0.35","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"35 °C, with the unit","field":"all","manual":true}],"solution":"35 °C\n\nMarker''s note. Forgetting to subtract the ice point length and computing 9.0 ÷ 22.0 × 100 gives 41 °C: award M1 only. The fundamental interval is the difference between the two fixed lengths, not the steam point length.","markerNote":"Forgetting to subtract the ice point length and computing 9.0 ÷ 22.0 × 100 gives 41 °C: award M1 only. The fundamental interval is the difference between the two fixed lengths, not the steam point length.","responseType":null,"answerType":"text"},"phy-p2-4-q3::d":{"answer":"308 K","modelResponse":"308 K","criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"adds 273 to the Celsius temperature","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"308 K, with the unit","field":"answer","check":{"type":"value","value":308,"tolerance":0.02,"unit":"K"}}],"solution":"308 K\n\nMarker''s note. Follow through from the candidate''s own earlier value. The unit is the kelvin, K, written without a degree sign. Writing 308 °K loses A1.","markerNote":"Follow through from the candidate''s own earlier value. The unit is the kelvin, K, written without a degree sign. Writing 308 °K loses A1.","responseType":null,"answerType":"value"},"phy-p2-4-q3::e":{"answer":"The bulb is thin-walled so that heat passes quickly through the glass to the liquid, and the thermometer responds quickly. The bore is narrow so that a small change in the volume of the liquid produces a large movement along the tube, making the thermometer more sensitive.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"thin walls give a quick response","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"a narrow bore gives greater sensitivity","field":"all","manual":true}],"solution":"The bulb is thin-walled so that heat passes quickly through the glass to the liquid, and the thermometer responds quickly. The bore is narrow so that a small change in the volume of the liquid produces a large movement along the tube, making the thermometer more sensitive.\n\nMarker''s note. The two ideas are distinct and each has its own mark. ''To make it more accurate'' is not either of them, since accuracy and sensitivity are not the same thing.","markerNote":"The two ideas are distinct and each has its own mark. ''To make it more accurate'' is not either of them, since accuracy and sensitivity are not the same thing.","responseType":null,"answerType":"text"},"phy-p2-4-q3::f":{"answer":"A thermocouple has a much wider range and can measure temperatures far above the boiling point of mercury.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"KC","description":"one genuine advantage, stated in a way that compares the two","field":"all","manual":true}],"solution":"A thermocouple has a much wider range and can measure temperatures far above the boiling point of mercury.\n\nMarker''s note. Accept: a wider range; a faster response because of its small thermal capacity; it can measure the temperature of a small object or a point; the reading can be taken at a distance or recorded electronically. Award one mark where the advantage is named but not related to the liquid-in-glass thermometer. ''It is better'' scores nothing.","markerNote":"Accept: a wider range; a faster response because of its small thermal capacity; it can measure the temperature of a small object or a point; the reading can be taken at a distance or recorded electronically. Award one mark where the advantage is named but not related to the liquid-in-glass thermometer. ''It is better'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-4-q4::a":{"answer":"Rubbing transfers electrons from the wool to the polythene. The polythene gains electrons and so becomes negatively charged. The cloth, having lost electrons, is left with an equal positive charge.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"electrons are transferred from the cloth to the rod","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the rod has a surplus of electrons and so is negative","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"the cloth is left positively charged","field":"all","manual":true}],"solution":"Rubbing transfers electrons from the wool to the polythene. The polythene gains electrons and so becomes negatively charged. The cloth, having lost electrons, is left with an equal positive charge.\n\nMarker''s note. Only electrons move. An answer which says the rod gains a negative charge from the cloth, or that protons move, loses B1. The charges are equal and opposite, which is worth saying but not required.","markerNote":"Only electrons move. An answer which says the rod gains a negative charge from the cloth, or that protons move, loses B1. The charges are equal and opposite, which is worth saying but not required.","responseType":null,"answerType":"text"},"phy-p2-4-q4::b":{"answer":"Like charges repel and unlike charges attract.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"like charges repel","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"unlike charges attract","field":"all","manual":true}],"solution":"Like charges repel and unlike charges attract.\n\nMarker''s note. Both halves are needed for both marks. Attraction alone does not prove a body is charged, since a charged body also attracts an uncharged one.","markerNote":"Both halves are needed for both marks. Attraction alone does not prove a body is charged, since a charged body also attracts an uncharged one.","responseType":null,"answerType":"text"},"phy-p2-4-q4::c":{"answer":"Bring the negatively charged rod near the sphere without touching it. The electrons in the sphere are repelled to the far side, leaving the near side positive. Earth the far side of the sphere by touching it, so that the repelled electrons flow away to earth. Remove the finger first, then remove the rod, and the sphere is left with an overall positive charge.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"brings the charged rod near without touching","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"electrons are repelled to the far side of the sphere","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"earths the sphere so that those electrons flow away","field":"all","manual":true},{"code":"B4","kind":"B","marks":1,"profile":"UK","description":"removes the earth connection before removing the rod","field":"all","manual":true}],"solution":"Bring the negatively charged rod near the sphere without touching it. The electrons in the sphere are repelled to the far side, leaving the near side positive. Earth the far side of the sphere by touching it, so that the repelled electrons flow away to earth. Remove the finger first, then remove the rod, and the sphere is left with an overall positive charge.\n\nMarker''s note. The order in B4 is the whole point of the method and is the mark most often lost. Removing the rod first lets the electrons flow back and the sphere ends up uncharged. The charge induced is opposite to that on the rod, so a negative rod gives a positive sphere; a candidate who ends with a negative sphere has described charging by contact and loses B2 and B4.","markerNote":"The order in B4 is the whole point of the method and is the mark most often lost. Removing the rod first lets the electrons flow back and the sphere ends up uncharged. The charge induced is opposite to that on the rod, so a negative rod gives a positive sphere; a candidate who ends with a negative sphere has described charging by contact and loses B2 and B4.","responseType":null,"answerType":"text"},"phy-p2-4-q4::d":{"answer":"The conductor is a thick copper strip running from a spike above the building to a plate buried in the ground. The sharp point causes charge to leak away from the building and partly discharge the cloud. If lightning does strike, the conductor carries the very large current safely to earth instead of through the building.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"a low resistance path from a point above the building to earth","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the sharp point allows charge to leak away, discharging the cloud","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"if struck, the current is carried safely to earth rather than through the building","field":"all","manual":true}],"solution":"The conductor is a thick copper strip running from a spike above the building to a plate buried in the ground. The sharp point causes charge to leak away from the building and partly discharge the cloud. If lightning does strike, the conductor carries the very large current safely to earth instead of through the building.\n\nMarker''s note. An answer which says only that the conductor ''attracts the lightning'' has half of B3 and does not earn it on its own: the useful part is where the current then goes.","markerNote":"An answer which says only that the conductor ''attracts the lightning'' has half of B3 and does not earn it on its own: the useful part is where the current then goes.","responseType":null,"answerType":"text"},"phy-p2-4-q4::e":{"answer":"Fuel flowing through the pipe rubs against it and charge builds up on the tanker. The chain or wire provides a path to earth so the charge leaks away steadily. Without it the charge could build until a spark jumps, and a spark near fuel vapour could cause an explosion.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"friction between the moving fuel and the pipe builds up charge","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"the earth connection lets the charge leak away safely","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"otherwise a spark could ignite the fuel or its vapour","field":"all","manual":true}],"solution":"Fuel flowing through the pipe rubs against it and charge builds up on the tanker. The chain or wire provides a path to earth so the charge leaks away steadily. Without it the charge could build until a spark jumps, and a spark near fuel vapour could cause an explosion.\n\nMarker''s note. B3 must name the spark and the ignition. ''It would be dangerous'' scores nothing.","markerNote":"B3 must name the spark and the ignition. ''It would be dangerous'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-4-q5::a":{"answer":"Hold the thumb and the first two fingers of the left hand at right angles to one another. The First finger points along the magnetic Field, the seCond finger along the Current, and the thuMb then gives the direction of the Motion or force.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"first finger is the field","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"second finger is the current","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"thumb is the motion or the force","field":"all","manual":true}],"solution":"Hold the thumb and the first two fingers of the left hand at right angles to one another. The First finger points along the magnetic Field, the seCond finger along the Current, and the thuMb then gives the direction of the Motion or force.\n\nMarker''s note. The three must be mutually at right angles, and the current is conventional current, from positive to negative. Do not withhold a mark for omitting either point unless the candidate states the opposite. The left hand is for the motor effect; a candidate who names the right hand has the wrong rule and scores nothing.","markerNote":"The three must be mutually at right angles, and the current is conventional current, from positive to negative. Do not withhold a mark for omitting either point unless the candidate states the opposite. The left hand is for the motor effect; a candidate who names the right hand has the wrong rule and scores nothing.","responseType":null,"answerType":"text"},"phy-p2-4-q5::b":{"answer":"Increase the current, increase the number of turns on the coil, and use a stronger magnet.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"increase the current","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"increase the number of turns","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"use a stronger magnetic field, or increase the area of the coil","field":"all","manual":true}],"solution":"Increase the current, increase the number of turns on the coil, and use a stronger magnet.\n\nMarker''s note. Accept inserting a soft iron core for B3. ''Make it bigger'' scores nothing.","markerNote":"Accept inserting a soft iron core for B3. ''Make it bigger'' scores nothing.","responseType":null,"answerType":"text"},"phy-p2-4-q5::c":{"answer":"The commutator reverses the direction of the current in the coil every half turn, just as the coil passes the vertical. Without it the force on each side would reverse relative to the coil and the coil would swing back, so it would oscillate instead of turning. With it the force on each side always acts the same way round and the coil keeps rotating in one direction.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"reverses the current in the coil every half turn","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"so the force on each side keeps acting the same way round","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"UK","description":"the coil turns continuously in one direction instead of oscillating","field":"all","manual":true}],"solution":"The commutator reverses the direction of the current in the coil every half turn, just as the coil passes the vertical. Without it the force on each side would reverse relative to the coil and the coil would swing back, so it would oscillate instead of turning. With it the force on each side always acts the same way round and the coil keeps rotating in one direction.\n\nMarker''s note. An answer which says the commutator ''makes the motor work'' scores nothing. The reversal of the current is what earns B1 and cannot be implied.","markerNote":"An answer which says the commutator ''makes the motor work'' scores nothing. The reversal of the current is what earns B1 and cannot be implied.","responseType":null,"answerType":"text"},"phy-p2-4-q5::d":{"answer":"A current is induced in the coil, which reverses each time the direction of motion reverses. The effect is electromagnetic induction.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"a current or an electromotive force is induced in the coil","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"names the effect as electromagnetic induction","field":"all","manual":true}],"solution":"A current is induced in the coil, which reverses each time the direction of motion reverses. The effect is electromagnetic induction.\n\nMarker''s note. Accept a deflection of a galvanometer connected to the coil for B1. A candidate who says the coil turns has confused the motor effect with induction.","markerNote":"Accept a deflection of a galvanometer connected to the coil for B1. A candidate who says the coil turns has confused the motor effect with induction.","responseType":null,"answerType":"text"},"phy-p2-4-q5::e":{"answer":"Move the magnet faster, and use a coil with more turns.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"UK","description":"move the magnet faster, or change the field more quickly","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"UK","description":"more turns on the coil, or a stronger magnet","field":"all","manual":true}],"solution":"Move the magnet faster, and use a coil with more turns.\n\nMarker''s note. The size of the induced electromotive force depends on the rate at which the field through the coil changes, so anything which increases that rate is acceptable.","markerNote":"The size of the induced electromotive force depends on the rate at which the field through the coil changes, so anything which increases that rate is acceptable.","responseType":null,"answerType":"text"},"phy-p2-4-q5::f":{"answer":"Direct current flows in one direction only, while alternating current reverses its direction regularly.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":2,"profile":"KC","description":"one clear difference, stated for both kinds of current","field":"all","manual":true}],"solution":"Direct current flows in one direction only, while alternating current reverses its direction regularly.\n\nMarker''s note. Accept a description of the voltage-time graphs: a steady horizontal line against a curve which crosses the axis. Award one mark where the candidate describes only one of the two.","markerNote":"Accept a description of the voltage-time graphs: a steady horizontal line against a curve which crosses the axis. Award one mark where the candidate describes only one of the two.","responseType":null,"answerType":"text"},"phy-p2-4-q6::a":{"answer":"92 protons, 143 neutrons and a nucleon number of 235.","modelResponse":"92 protons, 143 neutrons, nucleon number 235","criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"92 protons","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"KC","description":"143 neutrons, from 235 − 92","field":"answer","check":{"type":"value","value":143,"tolerance":0.02,"unit":"neutrons"}},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"nucleon number 235","field":"all","manual":true}],"solution":"92 protons, 143 neutrons and a nucleon number of 235.\n\nMarker''s note. The nucleon number is the mass number, the total of protons and neutrons, so it is read straight off the notation. A candidate who answers 235 neutrons has confused the nucleon number with the neutron number and loses A1 alone.","markerNote":"The nucleon number is the mass number, the total of protons and neutrons, so it is read straight off the notation. A candidate who answers 235 neutrons has confused the nucleon number with the neutron number and loses A1 alone.","responseType":null,"answerType":"value"},"phy-p2-4-q6::b":{"answer":"The nitrogen nucleus has mass number 14 and atomic number 7, and the beta particle has a charge number of −1.","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"balances the mass numbers: 14 = 14 + 0","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"7 for the atomic number of nitrogen","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"−1 for the beta particle","field":"all","manual":true}],"solution":"The nitrogen nucleus has mass number 14 and atomic number 7, and the beta particle has a charge number of −1.\n\nMarker''s note. In beta decay a neutron becomes a proton and an electron, so the atomic number rises by one while the mass number is unchanged. A candidate who writes 5 for the nitrogen has decreased the atomic number, which is alpha-like behaviour, and loses A1.","markerNote":"In beta decay a neutron becomes a proton and an electron, so the atomic number rises by one while the mass number is unchanged. A candidate who writes 5 for the nitrogen has decreased the atomic number, which is alpha-like behaviour, and loses A1.","responseType":null,"answerType":"text"},"phy-p2-4-q6::c":{"answer":"1/32 of the original nuclei","modelResponse":null,"criteria":[{"code":"M1","kind":"M","marks":1,"profile":"UK","description":"finds the number of half-lives: 40 ÷ 8.0","field":"all","manual":true},{"code":"M2","kind":"M","marks":1,"profile":"UK","description":"5 half-lives","field":"all","manual":true},{"code":"A1","kind":"A","marks":1,"profile":"UK","description":"halves the fraction five times, or uses (1/2)⁵","field":"all","manual":true},{"code":"A2","kind":"A","marks":1,"profile":"UK","description":"1/32, that is 0.031 or about 3.1 per cent","field":"all","manual":true}],"solution":"1/32 of the original nuclei\n\nMarker''s note. Follow through from the candidate''s own earlier value. Accept 1/32, 0.03125, 0.031 or 3.1 per cent. A candidate who answers 1/5 has divided rather than halved repeatedly: award M1 and M2 only. A candidate who gives the fraction decayed, 31/32, has answered the opposite question and loses A2.","markerNote":"Follow through from the candidate''s own earlier value. Accept 1/32, 0.03125, 0.031 or 3.1 per cent. A candidate who answers 1/5 has divided rather than halved repeatedly: award M1 and M2 only. A candidate who gives the fraction decayed, 31/32, has answered the opposite question and loses A2.","responseType":null,"answerType":"text"},"phy-p2-4-q6::d":{"answer":"Background radiation is the ionising radiation always present in the environment, whether or not a source is nearby. Two sources are rocks in the ground, such as granite giving off radon gas, and cosmic rays from space.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"radiation always present in the environment, from natural and artificial sources","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"first source","field":"all","manual":true},{"code":"B3","kind":"B","marks":1,"profile":"KC","description":"second, different source","field":"all","manual":true}],"solution":"Background radiation is the ionising radiation always present in the environment, whether or not a source is nearby. Two sources are rocks in the ground, such as granite giving off radon gas, and cosmic rays from space.\n\nMarker''s note. Accept as sources: rocks and soil, radon gas, cosmic rays, food and drink, building materials, medical X-rays, nuclear waste or fallout. Two rocks-based answers, such as granite and radon, count as one source.","markerNote":"Accept as sources: rocks and soil, radon gas, cosmic rays, food and drink, building materials, medical X-rays, nuclear waste or fallout. Two rocks-based answers, such as granite and radon, count as one source.","responseType":null,"answerType":"text"},"phy-p2-4-q6::e":{"answer":"Treating cancer with gamma radiation, and using a tracer to check the flow of a liquid in a pipeline.","modelResponse":null,"criteria":[{"code":"B1","kind":"B","marks":1,"profile":"KC","description":"first use","field":"all","manual":true},{"code":"B2","kind":"B","marks":1,"profile":"KC","description":"second, different use","field":"all","manual":true}],"solution":"Treating cancer with gamma radiation, and using a tracer to check the flow of a liquid in a pipeline.\n\nMarker''s note. Accept: radiotherapy, medical tracers, sterilising instruments or food, thickness gauging, detecting leaks in pipes, smoke alarms, carbon dating, checking welds. Generating electricity is not a use in medicine or industry in the sense the question means, but do not refuse it if a second valid use is given.","markerNote":"Accept: radiotherapy, medical tracers, sterilising instruments or food, thickness gauging, detecting leaks in pipes, smoke alarms, carbon dating, checking welds. Generating electricity is not a use in medicine or industry in the sense the question means, but do not refuse it if a second valid use is given.","responseType":null,"answerType":"text"}}'::jsonb;
begin
 select jsonb_array_length(criteria),
 (select sum((c->>'maxMarks')::integer) from jsonb_array_elements(criteria) c)
 into v_count,v_marks from spark_grading_private.rubrics_v2
 where subject_id='physics' and paper_id='spark-phy-p02-practice-4' and active=false and verification_status='draft';
 if v_count is distinct from 34 or v_marks is distinct from 100
 or (select count(*) from spark_grading_private.rubrics_v2 r
 cross join lateral jsonb_array_elements(r.criteria) c
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-4'
 and v_expected ? (c->>'id')) <> 34
 then raise exception 'Physics/IT exact draft source mismatch for spark-phy-p02-practice-4'; end if;
 update spark_grading_private.rubrics_v2 r set criteria=(
 select jsonb_agg(c || jsonb_build_object('sourceMarking',v_expected->(c->>'id')) order by ordinal)
 from jsonb_array_elements(r.criteria) with ordinality item(c,ordinal))
 where r.subject_id='physics' and r.paper_id='spark-phy-p02-practice-4' and r.active=false and r.verification_status='draft';
end $v2$;
do $v2$ declare v_count integer; v_marks integer; v_expected jsonb:='{"1-a":{"markScheme":["Award 1 mark for each relevant characteristic linked to the workload, for example high processing capacity, ability to handle many transactions/users, specialised control, reliability or large data volumes."],"responseType":"prose","profile":"Theory","prompt":"State TWO characteristics of a supercomputer that make it suitable for weather and disaster modelling."},"1-b":{"markScheme":["Router. 1 mark.","Role/function correctly stated as connecting or forwarding data between networks. 1 mark."],"responseType":"short","profile":"Theory","prompt":"Identify the MOST important hardware device used to connect the local networks to other networks."},"1-c":{"markScheme":["Intranet is private/internal to an organisation. 1 mark.","Extranet gives controlled access to authorised external users. 1 mark.","Clear distinction or suitable example. 1 mark."],"responseType":"prose","profile":"Theory","prompt":"Distinguish between an intranet and an extranet."},"1-d":{"markScheme":["Any three suitable media, for example twisted pair, coaxial cable, fibre-optic cable, infrared, microwave or satellite. 1 mark each."],"responseType":"prose","profile":"Theory","prompt":"State THREE transmission media that could be used in computer networks."},"1-e":{"markScheme":["Any two relevant factors such as accessibility, security, capacity, Internet availability/reliability or organisational policy. 1 mark each."],"responseType":"prose","profile":"Theory","prompt":"State TWO factors, other than cost, that should be considered when deciding whether to store operational files in the cloud."},"1-f":{"markScheme":["Validation checks whether data follows specified rules. 1 mark.","Verification checks whether data was entered/copied accurately. 1 mark.","Explanation that both address different kinds of data-entry error. 1 mark."],"responseType":"prose","profile":"Theory","prompt":"Explain why verification and validation are BOTH useful when new records are entered."},"1-g":{"markScheme":["Phishing/social-engineering attempt. 1 mark.","Any two suitable precautions such as verify sender/domain, do not follow suspicious link, type official address manually, do not reveal credentials, report the message. Up to 4 marks for two well-stated precautions."],"responseType":"prose","profile":"Theory","prompt":"The organisation receives an email asking staff to follow a link and enter their passwords urgently. Identify the likely threat and state TWO precautions staff should take."},"2-a":{"markScheme":["Data identified as raw facts/values. 1 mark.","Information identified as processed/organised data with meaning. 1 mark.","Relevant example from the spreadsheet. 1 mark."],"responseType":"prose","profile":"Theory","prompt":"Explain the difference between data and information, using the spreadsheet as part of your answer."},"2-b":{"markScheme":["Any two of authenticity, currency, relevance and bias, or equivalent. 1 mark each."],"responseType":"prose","profile":"Theory","prompt":"State TWO criteria that may be used to judge the reliability of information found on a website."},"2-c":{"markScheme":["Two valid system-software examples such as operating system/utilities. 2 marks.","One valid application-software example. 1 mark."],"responseType":"prose","profile":"Theory","prompt":"State TWO examples of system software and ONE example of application software."},"2-d":{"markScheme":["RAM described as temporary/volatile working memory. 1 mark.","Secondary storage described as longer-term/non-volatile storage. 1 mark.","Clear comparison. 1 mark."],"responseType":"prose","profile":"Theory","prompt":"Distinguish between RAM and secondary storage."},"2-e":{"markScheme":["Input, Processing, Output and Storage. 1 mark each."],"responseType":"prose","profile":"Theory","prompt":"State FOUR basic stages/components involved in the information-processing cycle."},"2-f":{"markScheme":["=B2*C2 or equivalent. 2 marks."],"responseType":"formula","profile":"Productivity Tools","prompt":"Write the spreadsheet formula that should be entered in D2 to calculate Total Cost."},"2-g":{"markScheme":["=SUM(D2:D3). 3 marks."],"responseType":"formula","profile":"Productivity Tools","prompt":"Write the function that should be entered in D4 to calculate the total of D2:D3."},"3-a":{"markScheme":["ShelterID."],"responseType":"short","profile":"Productivity Tools","prompt":"State the field that should be the primary key of SHELTER."},"3-b":{"markScheme":["ShelterID."],"responseType":"short","profile":"Productivity Tools","prompt":"State the field in REGISTRATION that should act as the foreign key."},"3-c":{"markScheme":["One-to-many. 2 marks.","Clear interpretation that one parent record can be linked to several child records. 1 mark."],"responseType":"prose","profile":"Productivity Tools","prompt":"State the relationship between SHELTER and REGISTRATION."},"3-d":{"markScheme":["Parish=''Kingston'' AND Status=''Active'', or equivalent."],"responseType":"query","profile":"Productivity Tools","prompt":"Write query criteria to select records where Parish is Kingston AND Status is Active."},"3-e":{"markScheme":["Form. 1 mark.","Suitable advantage such as easier/controlled data entry or clearer interface. 2 marks."],"responseType":"short","profile":"Productivity Tools","prompt":"Name the database object that is MOST suitable for user-friendly record entry and state ONE advantage of using it."},"3-f":{"markScheme":["Any three suitable features such as sorting, grouping, COUNT, SUM, AVERAGE, headings or selected fields. Award up to 4 marks."],"responseType":"prose","profile":"Productivity Tools","prompt":"State THREE features that could be used in a report to make the output more useful."},"3-g":{"markScheme":["Date/Time for Date. 2 marks.","Currency/number for Amount. 2 marks."],"responseType":"field-table","profile":"Productivity Tools","prompt":"State TWO suitable data types for a Date field and an Amount field."},"3-h":{"markScheme":["Uniquely identifies each record. 2 marks.","Helps prevent ambiguity/duplicates and supports relationships/retrieval. Up to 2 marks."],"responseType":"prose","profile":"Productivity Tools","prompt":"Explain why a primary key is important in a database table."},"4-a":{"markScheme":["Input: riskLevel, occupancy, capacity. 1 mark.","Process: calculate the score and compare with the threshold. 1 mark.","Output: ACCEPT or REVIEW. 1 mark."],"responseType":"ipo","profile":"Problem-Solving and Programming","prompt":"Construct an IPO chart for the evacuation score problem using the three inputs riskLevel, occupancy, capacity."},"4-b":{"markScheme":["Any two of finite, precise, unambiguous, clear flow of control, terminates. 2 marks.","One suitable explanation. 2 marks."],"responseType":"prose","profile":"Problem-Solving and Programming","prompt":"State TWO characteristics of a good algorithm and explain ONE of them."},"4-c":{"markScheme":["Read/input all three values. 2 marks.","Calculate SCORE using all three values. 2 marks.","Correct IF condition using threshold. 1 mark.","Display ACCEPT on true branch. 1 mark.","ELSE/otherwise branch. 1 mark.","Display REVIEW on false branch. 1 mark."],"responseType":"pseudocode","profile":"Problem-Solving and Programming","prompt":"Write language-neutral pseudocode that reads riskLevel, occupancy, capacity, calculates a SCORE using all three values, and displays ACCEPT when SCORE is at least 80, otherwise REVIEW."},"4-d":{"markScheme":["Use selected test data. 1 mark.","Record changing values/identifiers step by step. 1 mark.","Follow decision/control flow. 1 mark.","Compare actual result with expected result or identify logic errors. 1 mark."],"responseType":"prose","profile":"Problem-Solving and Programming","prompt":"Explain how a trace table or dry run could be used to test the algorithm."},"4-e":{"markScheme":["Syntax error breaks language rules and may prevent successful translation/execution. 1–2 marks.","Logic error allows execution but produces an incorrect result. 1–2 marks."],"responseType":"prose","profile":"Problem-Solving and Programming","prompt":"Distinguish between a syntax error and a logic error."},"4-f":{"markScheme":["Any three of meaningful variable names, useful comments, indentation and effective whitespace. 1 mark each."],"responseType":"prose","profile":"Problem-Solving and Programming","prompt":"State THREE features of good internal program documentation."}}'::jsonb;
